export const formatTravelPointDisplay = (pt) => {
  if (!pt) return '';
  if (typeof pt === 'string') return pt;
  const name = pt.name || '';
  const time = pt.time ? ` (${pt.time})` : '';
  const landmark = pt.landmark ? ` - ${pt.landmark}` : '';
  return `${name}${time}${landmark}`.trim();
};

export const formatTravelPointSimple = (pt) => {
  if (!pt) return '';
  if (typeof pt === 'string') return pt;
  const name = pt.name || '';
  const time = pt.time ? ` (${pt.time})` : '';
  return `${name}${time}`.trim();
};

export const extractVendorTravelPoints = (item) => {
  if (!item) return { boardingPoints: [], droppingPoints: [] };

  const parsePoints = (rawSingle, rawList, rawStoppings, defaultTime = '', isBoarding = true) => {
    const points = [];
    const seen = new Set();

    const addPoint = (val, time = '', landmark = '', id = undefined) => {
      if (!val || typeof val !== 'string') return;
      const clean = val.trim();
      if (!clean) return;
      if (clean.includes(',') || clean.includes('\n')) {
        const parts = clean.split(/[,\n]+/).map(p => p.trim()).filter(Boolean);
        for (const p of parts) addPoint(p, time, landmark, id);
        return;
      }
      const lower = clean.toLowerCase();
      if (!seen.has(lower)) {
        seen.add(lower);
        const finalTime = (time || defaultTime || '').trim();
        points.push({
          id,
          name: clean,
          departureTime: isBoarding ? finalTime : undefined,
          arrivalTime: !isBoarding ? finalTime : undefined,
          time: finalTime,
          landmark: (landmark || '').trim()
        });
      }
    };

    // Priority 1: Configured repeatable list from vendor route
    if (Array.isArray(rawList) && rawList.length > 0) {
      rawList.forEach(entry => {
        if (typeof entry === 'string') {
          addPoint(entry, defaultTime);
        } else if (entry && typeof entry === 'object' && entry.active !== false) {
          const name = entry.name || entry.point || entry.location || entry.stopName || entry.title || '';
          const time = entry.departureTime || entry.arrivalTime || entry.time || entry.timing || defaultTime || '';
          const landmark = entry.landmark || entry.address || '';
          const id = entry.id || entry._id || undefined;
          addPoint(name, time, landmark, id);
        }
      });
      return points;
    }

    // Priority 2: Fallback to legacy single point
    if (typeof rawSingle === 'string' && rawSingle.trim()) {
      addPoint(rawSingle, defaultTime);
    } else if (rawSingle && typeof rawSingle === 'object') {
      const timeVal = rawSingle.departureTime || rawSingle.arrivalTime || rawSingle.time || defaultTime;
      addPoint(rawSingle.name || rawSingle.point, timeVal, rawSingle.landmark || '', rawSingle.id);
    }

    // Priority 3: Fallback to route stoppings
    if (points.length === 0 && Array.isArray(rawStoppings) && rawStoppings.length > 0) {
      rawStoppings.forEach(stop => {
        if (typeof stop === 'string') {
          addPoint(stop);
        } else if (stop && typeof stop === 'object') {
          addPoint(stop.stopName || stop.name || stop.location, stop.time || '', '', stop.id);
        }
      });
    }

    return points;
  };

  const boardingPoints = parsePoints(
    item.boardingPoint || item.boarding_point || item.pickupPoint || item.pickup_point,
    item.boardingPoints || item.boarding_points || item.pickupPoints || item.pickup_points,
    null,
    item.boardingTime || item.busTiming || '',
    true
  );

  const droppingPoints = parsePoints(
    item.dropPoint || item.drop_point || item.droppingPoint || item.dropping_point || item.destination,
    item.droppingPoints || item.dropping_points || item.dropPoints || item.drop_points,
    null,
    item.arrivalTime || '',
    false
  );

  return { boardingPoints, droppingPoints };
};

const isPreviousDate = (year, month, day) => {
  const date = new Date(year, month, day);
  date.setHours(0, 0, 0, 0);
  
  const today = new Date();
  today.setHours(0, 0, 0, 0);
  
  return date.getTime() < today.getTime();
};

const isDateAlreadyBooked = (year, month, day) => {
  // Lock July 22nd and July 27th, 2026
  if (year === 2026 && month === 6 && (day === 22 || day === 27)) {
    return true;
  }
  // Also block 22nd and 27th of the current calendar month for easier demonstration
  const today = new Date();
  if (year === today.getFullYear() && month === today.getMonth() && (day === 22 || day === 27)) {
    return true;
  }
  return false;
};

const getGuestsCount = (product) => {
  if (!product) return null;
  const val = product.guests !== undefined ? product.guests : (product.maxGuests !== undefined ? product.maxGuests : product.capacity);
  if (val === undefined || val === null) return null;
  if (typeof val === 'object') {
    if (Array.isArray(val)) return val.length;
    if (val.count !== undefined) return val.count;
    if (val.value !== undefined) return val.value;
    return null;
  }
  return val;
};

const inferJobType = (p) => {
  if (!p) return 'Full-time';
  if (typeof p === 'string') return p;
  const direct = p.jobType || p.type || p.job_type || p.employmentType || p.workType;
  if (direct && String(direct).trim() && !['Job', 'Jobs', 'IT Jobs'].includes(String(direct).trim())) {
    return String(direct).trim();
  }
  const text = `${p.name || ''} ${p.category || ''} ${p.subcategory || ''} ${p.description || ''}`.toLowerCase();
  if (text.includes('part-time') || text.includes('part time')) return 'Part-time';
  if (text.includes('contract')) return 'Contract';
  if (text.includes('freelance')) return 'Freelance';
  if (text.includes('internship') || text.includes('intern')) return 'Internship';
  if (text.includes('work from home') || text.includes('remote') || text.includes('wfh')) return 'Remote / Work From Home';
  if (text.includes('full-time') || text.includes('full time')) return 'Full-time';
  return 'Full-time';
};

const inferExperience = (desc = '', title = '', pExp = '') => {
  if (pExp && String(pExp).trim()) {
    return String(pExp).trim();
  }
  const text = `${title} \n ${desc}`;
  const expMatch = text.match(/\b(\d+\s*(?:-|to|–)\s*\d+\s*(?:years?|yrs?)||\d+\+\s*(?:years?|yrs?)|freshers?|experienced)\b/i);
  if (expMatch && expMatch[0]) {
    return expMatch[0].replace(/yrs?/i, 'Years').trim();
  }
  const textLower = text.toLowerCase();
  if (textLower.includes('fresher') || textLower.includes('0-1 year') || textLower.includes('entry level')) return 'Fresher / 0-1 Year';
  if (textLower.includes('1-3 years') || textLower.includes('1 to 3 years') || textLower.includes('1-3 yrs')) return '1 - 3 Years';
  if (textLower.includes('2-5 years') || textLower.includes('2 to 5 years') || textLower.includes('2-5 yrs')) return '2 - 5 Years';
  if (textLower.includes('3-5 years') || textLower.includes('3+ years') || textLower.includes('3+ yrs')) return '3+ Years';
  if (textLower.includes('5+ years') || textLower.includes('5+ yrs') || textLower.includes('senior')) return '5+ Years';
  if (textLower.includes('full experience') || textLower.includes('need full experience') || textLower.includes('experienced')) return '3+ Years (Experienced)';
  return '1 - 3 Years';
};

const inferSkills = (title = '', category = '', desc = '', pSkills) => {
  if (Array.isArray(pSkills) && pSkills.length > 0) return pSkills;
  if (typeof pSkills === 'string' && pSkills.trim()) {
    return pSkills.split(',').map(s => s.trim()).filter(Boolean);
  }
  const text = `${title} ${category} ${desc}`.toLowerCase();
  if (text.includes('hr') || text.includes('recruiter') || text.includes('talent')) {
    return ['Recruitment', 'Talent Acquisition', 'HR Policies', 'Communication', 'Onboarding', 'ATS'];
  }
  if (text.includes('developer') || text.includes('software') || text.includes('full stack') || text.includes('frontend') || text.includes('backend') || text.includes('code') || text.includes('web') || text.includes('react') || text.includes('node') || text.includes('tech')) {
    return ['JavaScript', 'React.js', 'Node.js', 'Express.js', 'MongoDB', 'HTML5 & CSS3', 'Git & GitHub', 'REST APIs'];
  }
  if (text.includes('designer') || text.includes('ui') || text.includes('ux') || text.includes('graphic')) {
    return ['UI/UX Design', 'Figma', 'User Research', 'Wireframing', 'Prototyping', 'Adobe XD', 'Visual Design'];
  }
  if (text.includes('manager') || text.includes('management') || text.includes('operations') || text.includes('lead')) {
    return ['Operations Management', 'Team Leadership', 'Project Planning', 'Business Strategy', 'Stakeholder Management', 'Process Optimization'];
  }
  if (text.includes('sales') || text.includes('marketing') || text.includes('business development') || text.includes('growth')) {
    return ['Business Development', 'Client Acquisition', 'Sales Strategy', 'Lead Generation', 'CRM', 'Negotiation'];
  }
  if (text.includes('accountant') || text.includes('finance') || text.includes('tax') || text.includes('audit') || text.includes('tally')) {
    return ['Financial Accounting', 'GST & Taxation', 'Tally Prime', 'Balance Sheet', 'Financial Analysis', 'Excel'];
  }
  if (text.includes('travel') || text.includes('tourism') || text.includes('hospitality') || text.includes('hotel')) {
    return ['Customer Experience', 'Hospitality Management', 'Client Communication', 'Itinerary Planning', 'Reservations'];
  }
  if (text.includes('doctor') || text.includes('healthcare') || text.includes('medical') || text.includes('nurse')) {
    return ['Patient Care', 'Clinical Diagnosis', 'Medical Consultation', 'Treatment Planning', 'Healthcare Operations'];
  }
  return ['Professional Experience', 'Communication Skills', 'Problem Solving', 'Team Collaboration', 'Role-Specific Knowledge'];
};

const inferApplicationTips = (title = '', category = '', desc = '', pTips) => {
  if (Array.isArray(pTips) && pTips.length > 0) return pTips;
  if (typeof pTips === 'string' && pTips.trim()) {
    return pTips.split(/[,|\n]/).map(t => t.trim()).filter(Boolean);
  }
  const text = `${title} ${category} ${desc}`.toLowerCase();
  if (text.includes('developer') || text.includes('software') || text.includes('full stack') || text.includes('frontend') || text.includes('backend') || text.includes('code') || text.includes('web')) {
    return [
      "Please ensure your resume is updated with recent technical experience",
      "Tailor your project summary to highlight full stack & framework skills",
      "Include GitHub profile or live application links in your submission",
      "Double-check contact details before submitting your application"
    ];
  }
  if (text.includes('designer') || text.includes('ui') || text.includes('ux')) {
    return [
      "Provide a link to your Figma or Behance portfolio",
      "Showcase user research and wireframing case studies",
      "Highlight experience with modern design systems & UI tools",
      "Double-check portfolio links before submitting"
    ];
  }
  return [
    "Please ensure your resume is updated with recent experience",
    "Tailor your application summary to match role requirements",
    "Include relevant certifications and skill keywords",
    "Double-check contact info & phone number before submitting"
  ];
};

export function sanitizeJobLocation(loc, defaultLoc = 'Bangalore, Karnataka') {
  if (!loc || typeof loc !== 'string') return defaultLoc;
  const trimmed = loc.trim();
  const lower = trimmed.toLowerCase();
  if (
    lower.includes('need full experience') || 
    lower.includes('experience') || 
    lower.includes('description') || 
    trimmed.length > 35
  ) {
    return defaultLoc;
  }
  return trimmed;
}

export function sanitizeJobTitle(t, defaultTitle = 'Full Stack Developer') {
  if (!t || typeof t !== 'string') return defaultTitle;
  const trimmed = t.trim();
  if (trimmed.toLowerCase() === 'full') return 'Full Stack Developer';
  return trimmed;
}

export function formatDateYYYYMMDD(date) {
  if (!date) return '';
  const y = date.getFullYear();
  const m = String(date.getMonth() + 1).padStart(2, '0');
  const d = String(date.getDate()).padStart(2, '0');
  return `${y}-${m}-${d}`;
}

export function getFormattedModalDate(date) {
  if (!date) return '';
  const weekdays = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];
  const months = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
  return `${weekdays[date.getDay()]}, ${date.getDate()} ${months[date.getMonth()]} ${date.getFullYear()}`;
}

export function formatDateFromYYYYMMDD(dateStr) {
  if (!dateStr) return '';
  const parts = dateStr.split('-');
  if (parts.length !== 3) return dateStr;
  const d = new Date(parseInt(parts[0]), parseInt(parts[1]) - 1, parseInt(parts[2]));
  const weekdays = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];
  const months = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
  return `${weekdays[d.getDay()]}, ${d.getDate()} ${months[d.getMonth()]} ${d.getFullYear()}`;
}

export function formatDate(input) {
  if (!input) return '';
  if (input instanceof Date) {
    const weekdays = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];
    const months = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
    return `${weekdays[input.getDay()]}, ${input.getDate()} ${months[input.getMonth()]} ${input.getFullYear()}`;
  }
  const str = String(input).trim();
  if (str.includes('-')) {
    return formatDateFromYYYYMMDD(str);
  }
  const d = new Date(str);
  if (!isNaN(d.getTime())) {
    const weekdays = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];
    const months = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
    return `${weekdays[d.getDay()]}, ${d.getDate()} ${months[d.getMonth()]} ${d.getFullYear()}`;
  }
  return str;
}

export function generateUpcomingDates(startDateStr, count = 14, item = null) {
  const dates = [];
  let base = new Date();
  if (startDateStr && !isNaN(new Date(startDateStr + 'T00:00:00').getTime())) {
    base = new Date(startDateStr + 'T00:00:00');
  }
  const weekdays = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];
  const months = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];

  for (let i = 0; i < count; i++) {
    const d = new Date(base);
    d.setDate(base.getDate() + i);
    const dateStr = formatDateYYYYMMDD(d);
    
    // Check property-specific blocked dates if configured
    let isAvailable = true;
    if (Array.isArray(item?.unavailableDates) && item.unavailableDates.includes(dateStr)) {
      isAvailable = false;
    }
    if (Array.isArray(item?.blockedDates) && item.blockedDates.includes(dateStr)) {
      isAvailable = false;
    }

    dates.push({
      dateStr,
      dayNumber: d.getDate(),
      dayName: weekdays[d.getDay()],
      monthName: months[d.getMonth()],
      formatted: `${weekdays[d.getDay()]}, ${d.getDate()} ${months[d.getMonth()]}`,
      isAvailable
    });
  }
  return dates;
}

export function isJobCardItem(item) {
  if (!item) return false;
  const subCat = String(item.subNavbarCategory || '').toLowerCase().trim();
  const tag = String(item.tag || '').toLowerCase().trim();
  const cat = String(item.category || '').toLowerCase().trim();
  const mainCat = String(item.mainCategory || '').toLowerCase().trim();
  const subSub = String(item.subSubcategory || '').toLowerCase().trim();

  // Strict Exclusion: Food products must never be classified as Job cards
  const pFood = String(item.foodType || '').trim().toLowerCase();
  const name = String(item.name || item.title || '').trim().toLowerCase();
  const sub = String(item.subcategory || '').trim().toLowerCase();

  if (pFood && ['veg', 'non-veg', 'nonveg', 'idly', 'dosa', 'meals', 'standard'].includes(pFood)) {
    return false;
  }
  if (['dosa', 'idly', 'idli', 'south indian meals', 'biryani', 'parotta', 'chapati', 'poori', 'curry', 'meals'].some(k => name === k || name.includes(k) || sub === k || sub.includes(k) || subSub === k || subSub.includes(k))) {
    return false;
  }

  if (subCat === 'jobs' || subCat === 'job' || tag === 'jobs' || tag === 'job' || cat === 'jobs' || cat === 'job' || mainCat === 'jobs' || mainCat === 'job' || cat.includes('it jobs') || subSub.includes('it jobs') || item.jobTitle || item.jobLocation) {
    return true;
  }
  return false;
}

export function isBookingCartItem(item) {
  if (!item) return false;
  const subCat = String(item.subNavbarCategory || '');
  const tag = String(item.tag || '');
  const cat = String(item.category || '');
  const mainCat = String(item.mainCategory || '');
  const type = String(item.type || '');

  const bookingCategories = ['Services', 'Stay', 'Travel', 'Hospitals', 'Hospital', 'Doctors', 'Doctor', 'Appointments', 'Appointment'];
  if (bookingCategories.some(c => subCat === c || tag === c || cat === c || mainCat === c || type === c)) return true;
  if (item.bookingDate || item.bookingTime || item.checkInDate || item.checkInTime || item.bookingType || item.isBooking) return true;
  return false;
}

export function isJobCartItem(item) {
  if (!item) return false;
  if (isJobCardItem(item)) return true;
  const subCat = String(item.subNavbarCategory || '');
  const tag = String(item.tag || '');
  const cat = String(item.category || '');
  const mainCat = String(item.mainCategory || '');
  const type = String(item.type || '');

  const jobCategories = ['Jobs', 'Job', 'Careers', 'Career'];
  if (jobCategories.some(c => subCat === c || tag === c || cat === c || mainCat === c || type === c)) return true;
  return false;
}

export function isProductOrderCartItem(item) {
  if (!item) return false;
  const subCat = String(item.subNavbarCategory || item.mainCategory || item.tag || item.category || '').toLowerCase().trim();

  const noQtyCategories = ['services', 'service', 'stay', 'stays', 'travel', 'travels', 'jobs', 'job', 'hospitals', 'hospital', 'doctors', 'doctor', 'appointment'];
  const isExcluded = noQtyCategories.some(c => subCat === c || subCat.startsWith(c + ' ') || subCat.endsWith(' ' + c) || subCat.includes(c + ' booking'));
  if (isExcluded) return false;

  if (item.bookingDate || item.bookingTime || item.checkInDate || item.checkInTime || item.isBooking) return false;

  return true;
}

export function normalizeMainCatName(rawName) {
  if (!rawName) return '';
  const n = rawName.trim().toLowerCase();

  if (n === 'stay' || n === 'stays') return 'stay';
  if (n === 'food' || n === 'foods') return 'food';
  if (n === 'daily needs' || n === 'daily need' || n === 'daily-needs' || n === 'dailyneeds') return 'daily needs';
  if (n === 'jobs' || n === 'job') return 'jobs';
  if (n === 'services' || n === 'service') return 'services';
  if (n === 'travel' || n === 'travels') return 'travel';
  if (n === 'products' || n === 'product') return 'products';

  if (['hotel', 'hotels', 'homestay', 'resort', 'resorts', 'lodging', 'room', 'rooms', 'accommodation', 'villa', 'villas', 'pg', 'hostel', 'hostels', 'apartment', 'apartments', 'guest house', 'suite', 'suites'].some(k => n === k || n.includes(k))) return 'stay';
  if (['food', 'foods', 'restaurant', 'restaurants', 'dining', 'bakery', 'bakeries', 'cafe', 'cafes', 'biryani', 'biriyani', 'catering', 'sweets', 'sweet', 'ice cream', 'fast food', 'beverages', 'beverage', 'juice', 'juices', 'south indian', 'north indian', 'chinese', 'continental', 'dessert', 'desserts', 'snack', 'snacks', 'meal', 'meals', 'thali', 'dosa', 'parotta', 'pizza', 'burger'].some(k => n === k || n.includes(k))) return 'food';
  if (['daily need', 'daily needs', 'daily-needs', 'dailyneeds', 'grocery', 'groceries', 'supermarket', 'vegetable', 'vegetables', 'fruits', 'fruit', 'rice', 'eggs', 'egg', 'milk', 'dairy', 'pharmacy', 'medicine', 'medicines', 'organic', 'staples', 'personal care', 'provisions'].some(k => n === k || n.includes(k))) return 'daily needs';
  if (['job', 'jobs', 'hiring', 'recruitment', 'career', 'careers', 'it jobs', 'it domain', 'full time', 'part time', 'opening', 'openings', 'vacancy', 'vacancies', 'employment', 'work'].some(k => n === k || n.includes(k))) return 'jobs';
  if (['service', 'services', 'hospital', 'hospitals', 'doctor', 'doctors', 'clinic', 'clinics', 'healthcare', 'repair', 'repairs', 'plumbing', 'electrician', 'cleaning', 'salon', 'spa', 'consulting', 'consultant', 'fitness', 'gym', 'education', 'tutoring', 'photography', 'event management', 'maintenance', 'home care', 'pest control', 'laundry', 'carpentry', 'painter', 'legal', 'financial', 'insurance', 'it services', 'developer', 'design'].some(k => n === k || n.includes(k))) return 'services';
  if (['travel', 'travels', 'tour', 'tours', 'cab', 'cabs', 'taxi', 'taxis', 'bus', 'buses', 'flight', 'flights', 'train', 'trains', 'car rental', 'bike rental', 'tour package', 'ticket', 'tickets', 'transport'].some(k => n === k || n.includes(k))) return 'travel';

  return 'products';
}

export function resolveCustomerName(uName, currentUserName, emailStr) {
  if (uName && uName !== 'Connect Member' && !/^\d+$/.test(uName)) return uName;
  if (currentUserName && currentUserName !== 'Connect Member' && !/^\d+$/.test(currentUserName)) return currentUserName;
  if (emailStr && emailStr.includes('@')) {
    const prefix = emailStr.split('@')[0];
    if (prefix && !/^\d+$/.test(prefix)) {
      return prefix.charAt(0).toUpperCase() + prefix.slice(1);
    }
  }
  return uName || currentUserName || '';
}

export function getCanonicalTabName(item) {
  if (!item) return 'Products';
  const raw = item.subNavbarCategory || item.mainCategory || item.tag || item.category || '';
  const norm = normalizeMainCatName(raw);
  const map = {
    'services': 'Services',
    'products': 'Products',
    'daily needs': 'Daily Needs',
    'food': 'Food',
    'stay': 'Stay',
    'travel': 'Travel',
    'jobs': 'Jobs'
  };
  return map[norm] || 'Products';
}

export function sanitizePhoneInput(val, pincodeVal = '') {
  if (!val) return '';
  const digits = String(val).replace(/\D/g, '');
  if (digits.length < 10 || digits === String(pincodeVal)) return '';
  return val;
}

export function isPastTimeForSelectedDate(timeStr, dateStr) {
  if (!timeStr || !dateStr) return false;
  const now = new Date();
  const todayStr = formatDateYYYYMMDD(now);

  let normalizedDateStr = dateStr;
  if (dateStr.includes(',')) {
    const parsedDate = new Date(dateStr);
    if (!isNaN(parsedDate.getTime())) {
      normalizedDateStr = formatDateYYYYMMDD(parsedDate);
    }
  } else if (dateStr.includes('-')) {
    const parts = dateStr.split('-');
    if (parts.length === 3) {
      normalizedDateStr = `${parts[0]}-${String(parts[1]).padStart(2, '0')}-${String(parts[2]).padStart(2, '0')}`;
    }
  }

  if (normalizedDateStr < todayStr) return true;
  if (normalizedDateStr > todayStr) return false;

  let hours = 0;
  let minutes = 0;

  const match12 = String(timeStr).trim().match(/^(\d{1,2}):(\d{2})\s*(AM|PM)$/i);
  if (match12) {
    hours = parseInt(match12[1], 10);
    minutes = parseInt(match12[2], 10);
    const ampm = match12[3].toUpperCase();
    if (ampm === 'PM' && hours < 12) hours += 12;
    if (ampm === 'AM' && hours === 12) hours = 0;
  } else {
    const match24 = String(timeStr).trim().match(/^(\d{1,2}):(\d{2})$/);
    if (match24) {
      hours = parseInt(match24[1], 10);
      minutes = parseInt(match24[2], 10);
    }
  }

  const currentHours = now.getHours();
  const currentMinutes = now.getMinutes();

  if (hours < currentHours) return true;
  if (hours === currentHours && minutes <= currentMinutes) return true;
  return false;
}

export function getProductArchetype(product) {
  if (!product) return null;
  const text = `${product.name || ''} ${product.subcategory || ''} ${product.childCategory || ''} ${product.tag || ''} ${product.category || ''} ${product.description || ''}`.toLowerCase();
  
  if (/\b(laptop|notebook|macbook|chromebook|thinkpad|zenbook|ideapad|ultrabook)\b/.test(text)) return 'laptop';
  if (/\b(charger|adapter|charging cable|usb cable|type-c cable|lightning cable|power brick|power adapter)\b/.test(text)) return 'charger';
  if (/\b(power bank|powerbank|portable charger)\b/.test(text)) return 'powerbank';
  if (/\b(smartphone|smart phone|iphone|android phone|mobile phone|galaxy s|pixel \d)\b/.test(text) || (/\b(phone|mobile)\b/.test(text) && !/\b(charger|case|cover|holder|stand)\b/.test(text))) return 'phone';
  if (/\b(headphone|headphones|earphone|earphones|earbuds|airpods|headset|neckband|tws|bluetooth headphone)\b/.test(text)) return 'audio';
  if (/\b(smartwatch|smart watch|apple watch|fitness band|smart band)\b/.test(text)) return 'smartwatch';
  if (/\b(tablet|ipad|galaxy tab)\b/.test(text)) return 'tablet';
  if (/\b(television|smart tv|led tv|oled tv|qled tv|\btv\b)\b/.test(text)) return 'tv';
  if (/\b(camera|dslr|mirrorless|action cam|gopro)\b/.test(text)) return 'camera';
  if (/\b(refrigerator|fridge)\b/.test(text)) return 'refrigerator';
  if (/\b(washing machine|washer|dryer)\b/.test(text)) return 'washing_machine';
  if (/\b(microwave|oven|otg)\b/.test(text)) return 'microwave';
  if (/\b(ac|air conditioner)\b/.test(text)) return 'air_conditioner';
  if (/\b(router|wifi router|modem)\b/.test(text)) return 'networking';
  if (/\b(mouse|keyboard|keypad|trackpad)\b/.test(text)) return 'peripherals';
  if (/\b(monitor|display screen)\b/.test(text)) return 'monitor';
  
  // Fashion / Apparel
  if (/\b(lehenga|choli|ghagra)\b/.test(text)) return 'lehenga';
  if (/\b(saree|sari)\b/.test(text)) return 'saree';
  if (/\b(shirt|t-shirt|tshirt|tee)\b/.test(text)) return 'shirt';
  if (/\b(jeans|denim|trousers|pants)\b/.test(text)) return 'pants';
  if (/\b(dress|gown|frock|kurti|kurta)\b/.test(text)) return 'dress';
  if (/\b(shoe|shoes|sneaker|sneakers|boots|sandals|footwear)\b/.test(text)) return 'footwear';
  
  return null;
}

export function isTravelOrStayItem(item) {
  if (!item) return false;
  const norm = normalizeMainCatName(item.subNavbarCategory || item.mainCategory || item.category || item.tag || '');
  if (['products', 'food', 'daily needs', 'jobs', 'services', 'electronics', 'clothing', 'fashion', 'grocery', 'appliances'].includes(norm)) {
    return false;
  }
  if (norm === 'travel' || norm === 'stay') {
    return true;
  }

  // Never use roomType alone because Mongoose defaults roomType to 'Standard' on all products
  if (Boolean(item.boardingPoint || item.droppingPoint || (item.stayMode && item.stayMode !== 'Day Option'))) {
    return true;
  }

  const travelOrStayKeywords = [
    'travel', 'stay', 'hotel', 'resort', 'resorts', 'villa', 'villas', 'homestay',
    'lodge', 'lodging', 'pg', 'hostel', 'bus', 'buses', 'tour', 'tours',
    'flight', 'flights', 'cab', 'cabs', 'taxi', 'transport'
  ];

  const subNav = (item.subNavbarCategory || '').toLowerCase();
  const mainCat = (item.mainCategory || '').toLowerCase();
  const tag = (item.tag || '').toLowerCase();
  const cat = (item.category || '').toLowerCase();
  const type = (item.bookingType || '').toLowerCase();

  return travelOrStayKeywords.some(k => 
    subNav.includes(k) || mainCat.includes(k) || tag.includes(k) || cat.includes(k) || type.includes(k)
  );
}

export function isTravelOrStayCart(items) {
  if (!items || !Array.isArray(items) || items.length === 0) return false;
  return items.every(isTravelOrStayItem);
}

export function getOrderSupportReasons(ord) {
  if (!ord) return ['Order Defect / Damage', 'Missing Item / Wrong Product', 'Refund Request', 'Delayed Delivery'];
  const typeLower = (ord.type || '').toLowerCase();
  const subNav = (ord.subNavbarCategory || '').toLowerCase();
  const cat = (ord.category || '').toLowerCase();

  if (typeLower === 'job' || subNav === 'jobs') {
    return [
      'Application Status Inquiry',
      'Interview Reschedule Request',
      'Recruiter Unresponsive',
      'Withdraw Application'
    ];
  }
  if (typeLower === 'stay' || subNav === 'stay' || cat.includes('hotel') || cat.includes('stay') || cat.includes('resort') || Boolean(ord.checkInDate || ord.roomType)) {
    return [
      'Room Not Clean / Substandard',
      'Check-In Refused by Host',
      'Host / Front Desk Unreachable',
      'Cancellation & Refund Request',
      'Amenities / AC Not Working'
    ];
  }
  if (typeLower === 'travel' || subNav === 'travel' || cat.includes('travel') || cat.includes('bus') || Boolean(ord.boardingPoint || ord.droppingPoint)) {
    return [
      'Bus / Driver Delayed',
      'Boarding Point Issue',
      'Trip Cancellation & Refund',
      'Driver / Operator Unreachable',
      'Vehicle Breakdown / Poor Condition'
    ];
  }
  if (typeLower.includes('service') || subNav.includes('service')) {
    return [
      'Service Partner Delayed / No-Show',
      'Unsatisfactory Service Quality',
      'Overcharged / Extra Fee Demanded',
      'Service Partner Unreachable',
      'Cancellation & Refund Request'
    ];
  }
  if (subNav.includes('food') || cat.includes('food') || subNav.includes('daily') || cat.includes('daily') || cat.includes('grocery')) {
    return [
      'Food Stale / Bad Quality',
      'Spilled / Tampered Package',
      'Missing Food Item',
      'Delayed Food Delivery',
      'Wrong Food Delivered'
    ];
  }
  return [
    'Order Defect / Damage',
    'Missing Item / Wrong Product',
    'Refund Request',
    'Delayed Delivery',
    'Package Tampered'
  ];
}

export function getAuthoritativeSlotAvailability(timeStr, dateStr, item = null) {
  if (!timeStr || !dateStr) {
    return { isAvailable: false, status: 'Not Available', reason: 'Invalid date or time' };
  }

  const now = new Date();
  const todayStr = formatDateYYYYMMDD(now);
  let normalizedDate = dateStr;
  if (dateStr.includes(',')) {
    const pd = new Date(dateStr);
    if (!isNaN(pd.getTime())) normalizedDate = formatDateYYYYMMDD(pd);
  }
  if (normalizedDate < todayStr) {
    return { isAvailable: false, status: 'Not Available', reason: 'Selected date is in the past' };
  }

  let hours = 0;
  let minutes = 0;
  const match12 = String(timeStr).trim().match(/^(\d{1,2}):(\d{2})\s*(AM|PM)?$/i);
  if (match12) {
    hours = parseInt(match12[1], 10);
    minutes = parseInt(match12[2], 10);
    const ampm = match12[3] ? match12[3].toUpperCase() : '';
    if (ampm === 'PM' && hours < 12) hours += 12;
    if (ampm === 'AM' && hours === 12) hours = 0;
  } else {
    const match24 = String(timeStr).trim().match(/^(\d{1,2}):(\d{2})$/);
    if (match24) {
      hours = parseInt(match24[1], 10);
      minutes = parseInt(match24[2], 10);
    } else {
      return { isAvailable: false, status: 'Not Available', reason: 'Invalid time format' };
    }
  }

  // Operating window for check-in: 07:00 AM to 11:00 PM
  if (hours < 7 || hours >= 23) {
    return { isAvailable: false, status: 'Not Available', reason: 'Outside operating check-in hours (07:00 AM - 11:00 PM)' };
  }

  // Past time check for today
  if (normalizedDate === todayStr) {
    const currentH = now.getHours();
    const currentM = now.getMinutes();
    if (hours < currentH || (hours === currentH && minutes <= currentM)) {
      return { isAvailable: false, status: 'Not Available', reason: 'Time slot has already passed for today' };
    }
  }

  // Check vendor product specific availableTimeSlots configuration
  if (Array.isArray(item?.availableTimeSlots) && item.availableTimeSlots.length > 0) {
    const matchedConfig = item.availableTimeSlots.find(s => {
      const sTime = typeof s === 'string' ? s : s.time;
      return sTime && sTime.toLowerCase().trim() === timeStr.toLowerCase().trim();
    });
    if (matchedConfig) {
      const statusStr = typeof matchedConfig === 'string' ? 'Available' : (matchedConfig.status || 'Available');
      const isConfigAvail = statusStr === 'Available';
      return {
        isAvailable: isConfigAvail,
        status: isConfigAvail ? 'Available' : 'Not Available',
        reason: isConfigAvail ? '' : (matchedConfig.reason || 'Slot blocked by hotel property')
      };
    }
  }

  // Check vendor product specific blockedTimeSlots configuration
  if (Array.isArray(item?.blockedTimeSlots) && item.blockedTimeSlots.length > 0) {
    const isBlocked = item.blockedTimeSlots.some(s => {
      const sTime = typeof s === 'string' ? s : (s?.time || s?.slot);
      return sTime && sTime.toLowerCase().trim() === timeStr.toLowerCase().trim();
    });
    if (isBlocked) {
      return { isAvailable: false, status: 'Not Available', reason: 'Slot blocked by hotel property' };
    }
  }

  // Standard check-in hours within operating window (07:00 AM - 11:00 PM) are available unless specifically blocked
  return { isAvailable: true, status: 'Available', reason: '' };
}

export function isMainCategoryName(name) {
  if (!name) return true;
  const canonicalMains = ['services', 'products', 'daily needs', 'food', 'stay', 'travel', 'jobs'];
  const norm = normalizeCategoryName(name || '').trim().toLowerCase();
  return canonicalMains.includes(norm);
}

