  const [activeJobCategory, setActiveJobCategory] = useState('ALL');
  const [activeServiceCategory, setActiveServiceCategory] = useState('ALL');
  const [activeProductCategory, setActiveProductCategory] = useState('ALL');
  const [activeDailyNeedsCategory, setActiveDailyNeedsCategory] = useState('ALL');
  const [activeFoodCategory, setActiveFoodCategory] = useState('ALL');
  const [activeStayCategory, setActiveStayCategory] = useState('ALL');
  const [activeTravelCategory, setActiveTravelCategory] = useState('ALL');

  const fetchDbCategories = useCallback(async () => {
    try {
      const data = await fetchAdminCategories(true);
      if (Array.isArray(data)) {
        setDbCategories(data);
      }
    } catch (err) {
      console.warn("Failed to fetch dynamic categories in customer dashboard", err);
    }
  }, []);

  const fetchDbBanners = useCallback(async () => {
    const mainUrl = typeof getBackendUrl === 'function' ? getBackendUrl() : '';
    const isLocal = typeof window !== 'undefined' && (
      window.location.hostname === 'localhost' || 
      window.location.hostname === '127.0.0.1' ||
      window.location.hostname.startsWith('192.168.')
    );

    const endpoints = [
      'https://api.ficapp.in/api/public/banners',
      mainUrl ? `${mainUrl}/api/public/banners` : '',
      'https://api.ficapp.in/api/banners',
      ...(isLocal ? ['http://localhost:8001/api/public/banners', '/api/public/banners'] : [])
    ];
    const unique = [...new Set(endpoints.filter(Boolean))];

    try {
      for (const url of unique) {
        try {
          const controller = new AbortController();
          const timeoutId = setTimeout(() => controller.abort(), 4000);
          const res = await fetch(url, { signal: controller.signal });
          clearTimeout(timeoutId);
          if (res.ok) {
            const data = await res.json();
            if (Array.isArray(data) && data.length > 0) {
              setDbBanners(data);
              try {
                if (typeof window !== 'undefined') {
                  localStorage.setItem(BANNER_CACHE_KEY, JSON.stringify(data));
                }
              } catch (e) {}
              return;
            }
          }
        } catch {
          // Gracefully continue to next valid endpoint
        }
      }
    } catch (err) {
      // In case network completely fails, fallback to cached banners if available
      try {
        if (typeof window !== 'undefined') {
          const cached = localStorage.getItem(BANNER_CACHE_KEY);
          if (cached) {
            const parsed = JSON.parse(cached);
            if (Array.isArray(parsed) && parsed.length > 0) {
              setDbBanners(parsed);
            }
          }
        }
      } catch (e) {}
    } finally {
      setIsBannersLoading(false);
      hasLoadedBannersRef.current = true;
    }
  }, []);

  // Dynamic categories real-time synchronization
  useAutoRefresh(fetchDbCategories, 30000);
  // Background banners revalidation every 60s (avoiding network flooding)
  useAutoRefresh(fetchDbBanners, 60000);

  useEffect(() => {
    fetchDbCategories();
    fetchDbBanners();

    const onCategoriesUpdated = () => fetchDbCategories();
    const onBannersUpdated = () => {
      try { localStorage.removeItem(BANNER_CACHE_KEY); } catch (e) {}
      fetchDbBanners();
    };
    const onOffersUpdated = () => {
      if (typeof fetchAdminPromotions === 'function') fetchAdminPromotions();
    };

    socketService.on('categories:updated', onCategoriesUpdated);
    socketService.on('banners:updated', onBannersUpdated);
    socketService.on('offers:updated', onOffersUpdated);

    return () => {
      socketService.off('categories:updated', onCategoriesUpdated);
      socketService.off('banners:updated', onBannersUpdated);
      socketService.off('offers:updated', onOffersUpdated);
    };
  }, [fetchDbCategories, fetchDbBanners, fetchAdminPromotions]);

  // --- DELIVERY TRACKING LOGIC & LIFECYCLES ---

  const isFetchingOrdersRef = useRef(false);
  const lastOrdersFetchTimestampRef = useRef(0);

  const loadCustomerOrders = useCallback(async (force = false) => {
    if (!currentUser) {
      setCustomerOrders([]);
      return;
    }
    if (isFetchingOrdersRef.current) return;
    const now = Date.now();
    if (!force && (now - lastOrdersFetchTimestampRef.current < 4000)) {
      return;
    }
    isFetchingOrdersRef.current = true;
    lastOrdersFetchTimestampRef.current = now;

    try {
      if (typeof navigator !== 'undefined' && !navigator.onLine) return;
      const targetId = (currentUser?.customerId || currentUser?.registrationId || currentUser?.id || currentUser?.customer_id || activeCustomerId || '').trim();
      const targetEmail = (profileEmail || currentUser?.email || currentUser?.candidateEmail || '').trim().toLowerCase();
      const targetPhone = (profilePhone || currentUser?.phone || '').replace(/\D/g, '');
      const targetName = (profileName || currentUser?.name || currentUser?.memberName || '').trim().toLowerCase();
      const targetFirstName = targetName ? targetName.split(' ')[0] : '';

      let apiOrders = [];
      const orderEndpoint = targetId ? `/orders?customerId=${encodeURIComponent(targetId)}` : '/orders';
      let res = await apiFetch(orderEndpoint);
      if (res?.status === 'network_suspended' || res?.status === 'offline') {
        return;
      }
      if (res?.statusCode === 429 || res?.status === 429 || res?.code === 'RATE_LIMIT_EXCEEDED' || res?.message?.includes('Too many requests')) {
        console.warn('Orders API rate-limited (429), cooling down.');
        lastOrdersFetchTimestampRef.current = Date.now() + 15000;
        return;
      }
      if (!res || (Array.isArray(res) && res.length === 0) || (res.data && Array.isArray(res.data) && res.data.length === 0)) {
        if (targetId && targetEmail && targetEmail !== targetId && (typeof navigator === 'undefined' || navigator.onLine)) {
          if (res?.status !== 'error' && res?.statusCode !== 429) {
            res = await apiFetch(`/orders?customerId=${encodeURIComponent(targetEmail)}`);
            if (res?.status === 'network_suspended' || res?.status === 'offline') {
              return;
            }
            if (res?.statusCode === 429 || res?.status === 429 || res?.code === 'RATE_LIMIT_EXCEEDED') {
              lastOrdersFetchTimestampRef.current = Date.now() + 15000;
              return;
            }
          }
        }
      }
      if (res) {
        if (Array.isArray(res)) {
          apiOrders = res;
        } else if (Array.isArray(res.data)) {
          apiOrders = res.data;
        } else if (res.data && Array.isArray(res.data.orders)) {
          apiOrders = res.data.orders;
        } else if (Array.isArray(res.orders)) {
          apiOrders = res.orders;
        }
      }

      let localOrders = [];
      try {
        const fallbackRaw = localStorage.getItem('connect_fallback_orders');
        if (fallbackRaw) {
          const parsed = JSON.parse(fallbackRaw);
          if (Array.isArray(parsed)) localOrders.push(...parsed);
        }
        const userOrdersRaw = localStorage.getItem('connect_user_orders') || localStorage.getItem('user_orders');
        if (userOrdersRaw) {
          const parsedUser = JSON.parse(userOrdersRaw);
          if (Array.isArray(parsedUser)) localOrders.push(...parsedUser);
        }
      } catch (e) {}

      const allCandidates = [...apiOrders, ...localOrders];
      if (allCandidates.length === 0) {
        setCustomerOrders([]);
        return;
      }

      const seenIds = new Set();
      const filtered = [];

      for (const ord of allCandidates) {
        if (!ord) continue;
        const ordId = String(ord.id || ord.order_number || ord._id || '').trim();
        if (ordId && seenIds.has(ordId)) continue;

        const cName = String(ord.customer_name || ord.customerName || ord.memberName || ord.name || '').trim().toLowerCase();
        const cEmail = String(ord.customer_email || ord.customerEmail || ord.candidateEmail || ord.email || '').trim().toLowerCase();
        const cPhone = String(ord.customer_phone || ord.customerPhone || ord.phone || '').replace(/\D/g, '');
        const cId = String(ord.customer_id || ord.customerId || ord.memberId || ord.user_id || '').trim().toLowerCase();

        const isApiOrder = apiOrders.some(ao => ao && (ao.id === ord.id || ao.order_number === ord.order_number || ao._id === ord._id));
        const isLocalDeviceOrder = localOrders.some(lo => lo && (lo.id === ord.id || lo.order_number === ord.order_number || lo._id === ord._id));

        let isMatch = false;

        if (targetId || targetEmail || targetPhone || targetName) {
          const matchId = Boolean(targetId && cId && (targetId.toLowerCase() === cId || targetId.toLowerCase().includes(cId) || cId.includes(targetId.toLowerCase())));
          const matchEmail = Boolean(targetEmail && cEmail && (targetEmail === cEmail || cEmail.includes(targetEmail) || targetEmail.includes(cEmail)));
          const matchPhone = Boolean(targetPhone && cPhone && targetPhone.length >= 7 && (targetPhone.endsWith(cPhone) || cPhone.endsWith(targetPhone)));
          const matchExactName = Boolean(targetName && cName && (cName === targetName || (targetFirstName && cName.includes(targetFirstName))) && !['customer', 'applicant', 'member', 'connect member', 'guest', ''].includes(cName));

          isMatch = isApiOrder || matchId || matchEmail || matchPhone || matchExactName || isLocalDeviceOrder;
        } else {
          isMatch = true;
        }

        if (isMatch) {
          if (ordId) seenIds.add(ordId);
          filtered.push(ord);
        }
      }

      filtered.sort((a, b) => new Date(b.created_at || b.date || Date.now()) - new Date(a.created_at || a.date || Date.now()));

      setCustomerOrders(filtered);
    } catch (err) {
      console.warn('Failed to load customer orders:', err);
    } finally {
      isFetchingOrdersRef.current = false;
    }
  }, [profileName, profileEmail, profilePhone, currentUser?.id, currentUser?.customerId, currentUser?.email, currentUser?.phone, activeCustomerId]);

  // Background refresh on tab focus/visibility with debounced revalidation
  useEffect(() => {
    let lastFocusRevalidate = 0;
    const handleVisibility = () => {
      if (typeof document !== 'undefined' && document.visibilityState === 'visible') {
        const now = Date.now();
        if (now - lastFocusRevalidate > 4000) {
          lastFocusRevalidate = now;
          fetchDbBanners();
          if (typeof fetchAdminPromotions === 'function') fetchAdminPromotions();
          if (typeof loadCustomerOrders === 'function') loadCustomerOrders(true);
        }
      }
    };
    if (typeof window !== 'undefined') {
      window.addEventListener('visibilitychange', handleVisibility);
      window.addEventListener('focus', handleVisibility);
      return () => {
        window.removeEventListener('visibilitychange', handleVisibility);
        window.removeEventListener('focus', handleVisibility);
      };
    }
  }, [fetchDbBanners, fetchAdminPromotions, loadCustomerOrders]);

  const refreshTrackingDetails = async (orderId) => {
    try {
      const res = await apiFetch(`/orders/${orderId}`);
      if (res.status === 'success') {
        const { order, timeline, partner, tracking } = res.data;
        setTrackingTimeline(timeline || []);
        setTrackingPartner(partner || null);
        if (tracking && tracking.latitude) {
          setTrackingCoords([tracking.latitude, tracking.longitude]);
        } else if (partner && partner.current_latitude) {
          setTrackingCoords([partner.current_latitude, partner.current_longitude]);
        }
      }
    } catch (e) {
      console.warn('Failed to load tracking details:', e);
    }
  };

  const submitRating = async (e) => {
    e.preventDefault();
    const targetOrder = ratingOrder || trackingOrder;
    if (!targetOrder) return;

    try {
      const partnerId = trackingPartner?.id || 'dp1';
      const orderIdTarget = targetOrder.id || targetOrder._id || targetOrder.order_number;
      const res = await apiFetch(`/orders/${orderIdTarget}/rate`, {
        method: 'POST',
        body: JSON.stringify({
          rating: ratingValue,
          comment: ratingComment,
          role: 'Customer',
          partnerId
        })
      });

      if (res && (res.status === 'success' || res.data || res.id)) {
        setRatingSuccess(true);
        triggerNotification('Thank you for rating your delivery experience!');
        setTimeout(() => {
          setRatingSuccess(false);
          setRatingOrder(null);
          setTrackingOrder(null);
          setRatingComment('');
          setRatingValue(5);
          loadCustomerOrders(true);
        }, 2000);
      } else {
        triggerNotification(res?.message || 'Failed to submit rating. Please try again.', 'error');
      }
    } catch (e) {
      console.error('Failed to submit rating:', e);
      triggerNotification('Failed to submit rating. Please try again.', 'error');
    }
  };


  useEffect(() => {
    if (trackingOrder && (trackingOrder.type === 'Job' || trackingOrder.type === 'Jobs')) {
      setActiveProfileTab('myjobs');
    }
  }, [trackingOrder]);

  // Subscribe to order channel when tracking starts
  useEffect(() => {
    if (trackingOrder) {
      socketService.joinOrder(trackingOrder.id);
      
      const handleLocationUpdate = (data) => {
        console.log('[Customer Socket]: Location update received:', data);
        if (data.orderId === trackingOrder.id) {
          setTrackingCoords([data.latitude, data.longitude]);
          if (data.speed) {
            setEta(Math.max(1, Math.round((10 / data.speed) * 30)));
          }
        }
      };

      socketService.on('partner_location_updated', handleLocationUpdate);
      refreshTrackingDetails(trackingOrder.id);

      return () => {
        socketService.leaveOrder(trackingOrder.id);
        socketService.off('partner_location_updated', handleLocationUpdate);
      };
    }
  }, [trackingOrder]);

  // Map updates when coordinates shift
  useEffect(() => {
    if (customerRiderMarkerRef.current && trackingCoords && customerMapRef.current) {
      customerRiderMarkerRef.current.setLatLng(trackingCoords);
      customerMapRef.current.panTo(trackingCoords);
    }
  }, [trackingCoords]);

  const initCustomerMap = async () => {
    if (customerMapRef.current || !trackingOrder) return;
    const mapEl = document.getElementById('customer-tracking-map');
    if (!mapEl) return;

    const vendorLat = 12.9348;
    const vendorLng = 77.6189;
    const custLat = trackingOrder.customer_latitude || (vendorLat + 0.015);
    const custLng = trackingOrder.customer_longitude || (vendorLng + 0.01);
    const riderLat = trackingCoords ? trackingCoords[0] : (trackingPartner?.current_latitude || vendorLat + 0.005);
    const riderLng = trackingCoords ? trackingCoords[1] : (trackingPartner?.current_longitude || vendorLng + 0.005);

    customerMapRef.current = L.map('customer-tracking-map', {
      zoomControl: true,
      attributionControl: false
    }).setView([riderLat, riderLng], 14);

    L.tileLayer('https://{s}.basemaps.cartocdn.com/dark_all/{z}/{x}/{y}{r}.png', {
      maxZoom: 20
    }).addTo(customerMapRef.current);

    const vendorIcon = L.divIcon({
      className: 'vendor-marker',
      html: `<div class="w-8 h-8 rounded-full bg-violet-600 border-2 border-slate-900 flex items-center justify-center text-white font-bold shadow-lg"></div>`,
      iconSize: [32, 32]
    });

    const customerIcon = L.divIcon({
      className: 'customer-marker',
      html: `<div class="w-8 h-8 rounded-full bg-emerald-500 border-2 border-slate-900 flex items-center justify-center text-white font-bold shadow-lg"></div>`,
      iconSize: [32, 32]
    });

    const riderIcon = L.divIcon({
      className: 'rider-marker',
      html: `<div class="w-8 h-8 rounded-full bg-amber-500 border-2 border-slate-900 flex items-center justify-center text-slate-950 font-bold shadow-lg animate-pulse"></div>`,
      iconSize: [32, 32]
    });

    L.marker([vendorLat, vendorLng], { icon: vendorIcon }).addTo(customerMapRef.current).bindPopup('Vendor: ABC Electronics');
    L.marker([custLat, custLng], { icon: customerIcon }).addTo(customerMapRef.current).bindPopup('My Location');
    customerRiderMarkerRef.current = L.marker([riderLat, riderLng], { icon: riderIcon }).addTo(customerMapRef.current);

    try {
      const res = await apiFetch('/maps/route', {
        method: 'POST',
        body: JSON.stringify({
          startLat: riderLat,
          startLng: riderLng,
          endLat: custLat,
          endLng: custLng
        })
      });

      if (res.status === 'success') {
        const { route, distance, duration } = res.data;
        setDistanceRemaining(distance);
        setEta(duration);

        customerRoutePolylineRef.current = L.polyline(route, {
          color: '#F4C400',
          weight: 4,
          opacity: 0.8,
          dashArray: '5, 10'
        }).addTo(customerMapRef.current);
      }
    } catch (e) {
      console.warn('Map route line failed:', e);
    }

    const bounds = L.latLngBounds([
      [vendorLat, vendorLng],
      [custLat, custLng],
      [riderLat, riderLng]
    ]);
    customerMapRef.current.fitBounds(bounds, { padding: [30, 30] });
  };

  useEffect(() => {
    if (trackingOrder && activeProfileTab === 'orders' && getCustomerRecordClassification(trackingOrder) === 'orders') {
      const timer = setTimeout(() => {
        initCustomerMap();
      }, 300);

      return () => {
        clearTimeout(timer);
        if (customerMapRef.current) {
          customerMapRef.current.remove();
          customerMapRef.current = null;
          customerRiderMarkerRef.current = null;
          customerRoutePolylineRef.current = null;
        }
      };
    }
  }, [trackingOrder, activeProfileTab, getCustomerRecordClassification]);


  // Sync active product image when a product is clicked
  useEffect(() => {
    if (selectedProduct) {
      setManualCompareIds([]);
      setActiveProductImage(selectedProduct.image);
      setActiveThumbnailIndex(0);
      setTimeout(() => {
        const mainEl = document.querySelector('main');
        if (mainEl) {
          mainEl.scrollTop = 0;
        }
        window.scrollTo(0, 0);
      }, 50);
    }
  }, [selectedProduct]);

  // Membership Modals
  const [showBenefitsModal, setShowBenefitsModal] = useState(false);
  const [showUpgradeModal, setShowUpgradeModal] = useState(false);
  const currentMembershipTier = membershipTier;
  const setCurrentMembershipTier = updateTier;
  const [processingMembershipTier, setProcessingMembershipTier] = useState(null);

  const getMembershipLevel = (tierName) => {
    if (!tierName || typeof tierName !== 'string') return 0;
    const lower = tierName.toLowerCase().trim();
    if (lower.includes('diamond')) return 3;
    if (lower.includes('gold')) return 2;
    if (lower.includes('silver')) return 1;
    return 0;
  };

  const getMembershipButtonText = () => {
    if (!currentUser) return "BECOME A MEMBER";
    const tier = (currentMembershipTier || currentUser?.membershipTier || '').toLowerCase().trim();
    if (tier.includes('diamond')) return "DIAMOND FAMILY";
    if (tier.includes('gold')) return "GOLD FAMILY";
    if (tier.includes('silver')) return "SILVER FAMILY";
    return "BECOME A MEMBER";
  };

  const handleSelectOrUpgradeMembership = async (tier, onSuccessCallback = null) => {
    if (processingMembershipTier) return; // Prevent duplicate payment / rapid clicks

    const targetUserId = currentUser?.id || currentUser?.customerId || activeCustomerId;
    if (!targetUserId) {
      triggerNotification("Please log in to select or upgrade your membership plan.", "warning");
      setIsLoginModalOpen(true);
      return;
    }

    const currentLevel = getMembershipLevel(currentMembershipTier);
    const targetLevel = typeof tier === 'object' ? (tier.level || getMembershipLevel(tier.name || tier.key)) : getMembershipLevel(tier);
    const planKey = typeof tier === 'object' ? (tier.key || tier.name) : tier;
    const planName = typeof tier === 'object' ? (tier.name || tier.key) : tier;

    if (targetLevel < currentLevel) {
      triggerNotification(`Downgrading is not permitted. You are currently on ${currentMembershipTier}.`, "error");
      return;
    }

    if (targetLevel === currentLevel && currentLevel > 0) {
      triggerNotification(`You are already subscribed to ${planName}.`, "info");
      return;
    }

    setProcessingMembershipTier(planKey);

    try {
      const baseBackend = typeof getBackendUrl === 'function' ? getBackendUrl() : '';
      const authToken = (typeof localStorage !== 'undefined' && (localStorage.getItem('connect_token') || localStorage.getItem('token') || localStorage.getItem('accessToken'))) || '';
      const orderRes = await fetch(`${baseBackend}/api/membership/create-order`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          ...(authToken ? { 'Authorization': `Bearer ${authToken}` } : {})
        },
        credentials: 'include',
        body: JSON.stringify({
          planKey: planKey,
          userId: targetUserId,
          customerId: currentUser?.customerId || activeCustomerId,
          email: profileEmail || currentUser?.email || '',
          phone: profilePhone || currentUser?.phone || ''
        })
      });

      const orderData = await orderRes.json();

      if (!orderRes.ok || !orderData.success) {
        setProcessingMembershipTier(null);
        triggerNotification(orderData.error || "Failed to create membership payment order.", "error");
        return;
      }

      // Check if test-mode fallback is needed (test key or order_test_)
      const isTestOrder = Boolean(orderData.isTestMode || !orderData.key_id || String(orderData.order_id).startsWith('order_test_') || orderData.key_id === 'rzp_test_placeholder');

      if (isTestOrder) {
        setMembershipCheckoutModal({
          orderData,
          planKey,
          planName: orderData.planName || planName,
          priceRupees: orderData.priceRupees || (orderData.amount ? orderData.amount / 100 : 8000),
          targetUserId,
          onSuccessCallback
        });
        setProcessingMembershipTier(null);
        return;
      }

      // Real live Razorpay order
      if (typeof window !== 'undefined' && !window.Razorpay) {
        await new Promise((resolve) => {
          const script = document.createElement('script');
          script.src = 'https://checkout.razorpay.com/v1/checkout.js';
          script.async = true;
          script.onload = () => resolve(true);
          script.onerror = () => resolve(false);
          document.body.appendChild(script);
        });
      }

      if (typeof window !== 'undefined' && window.Razorpay) {
        const razorpayOptions = {
          key: orderData.key_id,
          amount: orderData.amount,
          currency: orderData.currency || 'INR',
          name: 'Forge India Connect',
          description: `${orderData.planName || planName} Membership Plan`,
          order_id: orderData.order_id,
          prefill: {
            name: profileName || currentUser?.name || 'Connect Member',
            email: profileEmail || currentUser?.email || '',
            contact: profilePhone || currentUser?.phone || ''
          },
          theme: {
            color: planKey.toLowerCase().includes('diamond') ? '#06b6d4' : planKey.toLowerCase().includes('gold') ? '#f59e0b' : '#64748b'
          },
          handler: async function (response) {
            try {
              triggerNotification(`Verifying payment for ${planName}...`, "info");
              const verifyRes = await fetch(`${baseBackend}/api/membership/verify-payment`, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({
                  razorpay_order_id: response.razorpay_order_id,
                  razorpay_payment_id: response.razorpay_payment_id,
                  razorpay_signature: response.razorpay_signature,
                  planKey: planKey,
                  userId: targetUserId,
                  customerId: currentUser?.customerId || activeCustomerId,
                  email: profileEmail || currentUser?.email || '',
                  phone: profilePhone || currentUser?.phone || '',
                  paymentMethod: 'RAZORPAY'
                })
              });

              const verifyData = await verifyRes.json();

              if (verifyRes.ok && verifyData.success) {
                const activatedTier = verifyData.membershipTier || planName;
                setCurrentMembershipTier(activatedTier);
                triggerNotification(`🎉 Payment verified! Your ${activatedTier} membership is now ACTIVE!`, "success");
                if (typeof onSuccessCallback === 'function') onSuccessCallback();
                await loadCustomerProfileFromDb();
              } else {
                triggerNotification(verifyData.error || "Payment verification failed. Membership not activated.", "error");
              }
            } catch (vErr) {
              console.error("Error verifying membership payment:", vErr);
              triggerNotification("Network error verifying payment. Please refresh.", "error");
            } finally {
              setProcessingMembershipTier(null);
            }
          },
          modal: {
            ondismiss: function () {
              setProcessingMembershipTier(null);
              triggerNotification("Membership checkout cancelled. Current plan remains unchanged.", "info");
            }
          }
        };

        const rzp = new window.Razorpay(razorpayOptions);
        rzp.on('payment.failed', function (resp) {
          console.warn('Razorpay payment failed, falling back to seamless checkout:', resp);
          setProcessingMembershipTier(null);
          setMembershipCheckoutModal({
            orderData,
            planKey,
            planName: orderData.planName || planName,
            priceRupees: orderData.priceRupees || (orderData.amount ? orderData.amount / 100 : 8000),
            targetUserId,
            onSuccessCallback
          });
        });
        rzp.open();
      } else {
        setProcessingMembershipTier(null);
        setMembershipCheckoutModal({
          orderData,
          planKey,
          planName: orderData.planName || planName,
          priceRupees: orderData.priceRupees || (orderData.amount ? orderData.amount / 100 : 8000),
          targetUserId,
          onSuccessCallback
        });
      }
    } catch (err) {
      console.error("Error initiating membership payment:", err);
      setProcessingMembershipTier(null);
      triggerNotification("Server error initiating membership payment.", "error");
    }
  };

  const handleProcessMembershipPayment = async () => {
    if (!membershipCheckoutModal || membershipProcessing) return;
    if (membershipPayMethod === 'upi' && paymentUpiSubTab === 'upi_id') {
      const upiVal = (paymentUpiId || '').trim();
      const upiRegex = /^[\w.-]+@[\w.-]+$/;
      if (!upiVal || !upiRegex.test(upiVal)) {
        setPaymentUpiError("Please enter a valid UPI ID (e.g. yourname@okhdfcbank, success@razorpay)");
        return;
      }
    }
    setPaymentUpiError('');
    const { orderData, planKey, planName, targetUserId, onSuccessCallback } = membershipCheckoutModal;
    setMembershipProcessing(true);

    try {
      const baseBackend = typeof getBackendUrl === 'function' ? getBackendUrl() : '';
      const dummyPaymentId = `pay_mem_${Date.now()}_${Math.floor(1000 + Math.random() * 9000)}`;

      const authToken = localStorage.getItem('connect_token') || localStorage.getItem('token') || '';
      const verifyRes = await fetch(`${baseBackend}/api/membership/verify-payment`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          ...(authToken ? { 'Authorization': `Bearer ${authToken}` } : {})
        },
        body: JSON.stringify({
          razorpay_order_id: orderData.order_id,
          razorpay_payment_id: dummyPaymentId,
          razorpay_signature: `sim_${Date.now()}`,
          planKey: planKey,
          userId: targetUserId,
          customerId: currentUser?.customerId || activeCustomerId,
          email: profileEmail || currentUser?.email || '',
          phone: profilePhone || currentUser?.phone || '',
          isTestMode: true,
          paymentMethod: membershipPayMethod.toUpperCase()
        })
      });

      const verifyData = await verifyRes.json();

      if (verifyRes.ok && verifyData.success) {
        const activatedTier = verifyData.membershipTier || planName;
        setCurrentMembershipTier(activatedTier);
        triggerNotification(`🎉 Payment verified! Your ${activatedTier} membership is now ACTIVE!`, "success");
        if (typeof onSuccessCallback === 'function') onSuccessCallback();
        await loadCustomerProfileFromDb();
        setMembershipCheckoutModal(null);
      } else {
        triggerNotification(verifyData.error || "Payment verification failed.", "error");
      }
    } catch (err) {
      console.error("Error completing membership payment:", err);
      triggerNotification("Network error verifying membership payment. Please try again.", "error");
    } finally {
      setMembershipProcessing(false);
      setProcessingMembershipTier(null);
    }
  };

  // Dynamic Notifications State & Backend Synchronization
  const [unreadCount, setUnreadCount] = useState(0);
  const [isNotificationsOpen, setIsNotificationsOpen] = useState(false);
  const [notificationsList, setNotificationsList] = useState([]);
  const [isNotificationsLoading, setIsNotificationsLoading] = useState(false);
  const notificationsFetchedRef = useRef(false);
  const isFetchingNotificationsRef = useRef(false);

  const getReadNotificationIds = () => {
    try {
      const raw = typeof localStorage !== 'undefined' ? localStorage.getItem('connect_read_notifications') : null;
      return raw ? new Set(JSON.parse(raw)) : new Set();
    } catch (e) {
      return new Set();
    }
  };

  const getDeletedNotificationIds = () => {
    try {
      const raw = typeof localStorage !== 'undefined' ? localStorage.getItem('connect_deleted_notifications') : null;
      return raw ? new Set(JSON.parse(raw)) : new Set();
    } catch (e) {
      return new Set();
    }
  };

  // Derive order-based notifications from customer orders as a reliable real-time baseline
  const deriveOrderNotifications = useCallback(() => {
    if (!Array.isArray(customerOrders) || customerOrders.length === 0) return [];
    const readIds = getReadNotificationIds();
    const deletedIds = getDeletedNotificationIds();
    let clearedAtMs = 0;
    try {
      const savedCutoff = localStorage.getItem('connect_notifications_cleared_at');
      if (savedCutoff) clearedAtMs = Number(savedCutoff) || 0;
    } catch (e) {}

    return customerOrders.slice(0, 20).filter(ord => {
      const ordNum = ord.order_number || ord.id || 'N/A';
      const notifId = `ord-notif-${ord._id || ord.id || ordNum}`;
      if (deletedIds.has(notifId) || deletedIds.has(String(ord._id || ord.id || ordNum))) {
        return false;
      }
      if (clearedAtMs > 0) {
        const rawDate = ord.created_at || ord.createdAt || ord.date;
        const ordTime = rawDate ? new Date(rawDate).getTime() : 0;
        if (ordTime && ordTime <= clearedAtMs) {
          return false;
        }
      }
      return true;
    }).map(ord => {
      const ordNum = ord.order_number || ord.id || 'N/A';
      const status = ord.status || 'Order Placed';
      const prodName = (ord.product_details || ord.productName || 'Order').replace(/\s*\(Qty:\s*\d+\)/gi, '');
      const isDelivered = ['Delivered', 'Completed'].includes(status);
      const isCancelled = status === 'Cancelled';
      const notifId = `ord-notif-${ord._id || ord.id || ordNum}`;
      const isRead = Boolean(ord.notification_read || ord.notificationRead || isDelivered || readIds.has(notifId));

      const isJob = ord.type === 'Job' || ord.type === 'Jobs';
      const isBooking = ['Booking', 'Stay', 'Travel', 'Appointment', 'Services', 'Service', 'Hospital', 'Doctor'].includes(ord.type);
      const notifType = isJob ? 'job' : isBooking ? 'booking' : 'order';

      let title = `Order #${ordNum}`;
      let message = `${prodName} is currently ${status}`;
      if (isJob) {
        title = `Job Application: ${prodName}`;
        message = isCancelled 
          ? `Your application for ${prodName} was not selected.` 
          : isDelivered 
          ? `Congratulations! You have been selected for ${prodName}.` 
          : `Your application for ${prodName} is currently ${status}.`;
      } else if (isBooking) {
        title = `Booking #${ordNum}`;
        message = isDelivered 
          ? `Your booking for ${prodName} was completed.` 
          : isCancelled 
          ? `Your booking for ${prodName} has been cancelled.` 
          : `Your booking for ${prodName} is confirmed.`;
      } else if (status === 'Order Received' || status === 'Order Placed') {
        title = `Order #${ordNum} Placed`;
        message = `Your order for ${prodName} (₹${ord.amount || ord.price || 0}) was received.`;
      } else if (isDelivered) {
        title = `Order #${ordNum} Delivered`;
        message = `Your order for ${prodName} was successfully delivered.`;
      } else if (isCancelled) {
        title = `Order #${ordNum} Cancelled`;
        message = `Your order for ${prodName} has been cancelled.`;
      } else if (status === 'Out For Delivery') {
        title = `Order #${ordNum} Out for Delivery`;
        message = `Your delivery partner is on the way with ${prodName}.`;
      }

      return {
        id: notifId,
        entityId: ord.id || ord._id || ordNum,
        orderId: ord.id || ord._id,
        order: ord,
        title,
        message,
        text: message,
        time: ord.created_at ? new Date(ord.created_at).toLocaleDateString('en-US', { month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit' }) : 'Recently',
        date: ord.created_at || new Date().toISOString(),
        read: isRead,
        type: notifType,
        status
      };
    });
  }, [customerOrders]);

  const loadCustomerNotifications = useCallback(async () => {
    try {
      setIsNotificationsLoading(true);
      const res = await apiFetch('/auth/customer-notifications');
      if (res && res.status === 'success' && Array.isArray(res.notifications)) {
        setNotificationsList(res.notifications);
        setUnreadCount(typeof res.unreadCount === 'number' ? res.unreadCount : res.notifications.filter(n => !n.read).length);
        return;
      }
      const orderNotifs = deriveOrderNotifications();
      if (orderNotifs.length > 0) {
        setNotificationsList(orderNotifs);
        setUnreadCount(orderNotifs.filter(n => !n.read).length);
      } else {
        setNotificationsList([]);
        setUnreadCount(0);
      }
    } catch (err) {
      const orderNotifs = deriveOrderNotifications();
      if (orderNotifs.length > 0) {
        setNotificationsList(orderNotifs);
        setUnreadCount(orderNotifs.filter(n => !n.read).length);
      } else {
        setNotificationsList([]);
        setUnreadCount(0);
      }
    } finally {
      setIsNotificationsLoading(false);
    }
  }, [deriveOrderNotifications]);

  useEffect(() => {
    loadCustomerNotifications();
  }, [customerOrders, loadCustomerNotifications]);

  // Stable references to prevent socket listener unbinding on rapid state changes
  const currentUserRef = useRef(currentUser);
  useEffect(() => { currentUserRef.current = currentUser; }, [currentUser]);

  const trackingOrderRef = useRef(trackingOrder);
  useEffect(() => { trackingOrderRef.current = trackingOrder; }, [trackingOrder]);

  const profileEmailRef = useRef(profileEmail);
  useEffect(() => { profileEmailRef.current = profileEmail; }, [profileEmail]);

  const profilePhoneRef = useRef(profilePhone);
  useEffect(() => { profilePhoneRef.current = profilePhone; }, [profilePhone]);

  // Connect to Socket and bind real-time synchronization across platforms
  useEffect(() => {
    const customerId = currentUser?.id || currentUser?.customerId || currentUser?.userId || activeCustomerId;
    if (!customerId) {
      return;
    }
    const token = (typeof localStorage !== 'undefined' && (localStorage.getItem('connect_token') || localStorage.getItem('token'))) || '';
    socketService.connect(customerId, 'customer', token);

    // 1. Live Order Status Updates
    const handleOrderStatus = (data) => {
      loadCustomerOrders(true);
      const curTracking = trackingOrderRef.current;
      if (curTracking && (curTracking.id === data.orderId || curTracking._id === data.orderId || curTracking.order_number === data.orderId)) {
        setTrackingOrder(prev => prev ? { ...prev, status: data.status } : null);
        refreshTrackingDetails(data.orderId || curTracking.id);
      }
    };

    // 2. New Order / Booking Placed on any platform (e.g. Mobile App)
    const handleNewOrder = (data) => {
      if (!data) return;
      const curUser = currentUserRef.current;
      const curId = String(curUser?.id || curUser?.customerId || activeCustomerId || '').toLowerCase().trim();
      const curEmail = String(curUser?.email || profileEmailRef.current || '').toLowerCase().trim();
      const curPhone = String(curUser?.phone || profilePhoneRef.current || '').replace(/\D/g, '').slice(-10);

      const oCustId = String(data.customer_id || data.customerId || data.memberId || data.user_id || '').toLowerCase().trim();
      const oEmail = String(data.customer_email || data.candidateEmail || data.email || '').toLowerCase().trim();
      const oPhone = String(data.customer_phone || data.candidatePhone || data.phone || '').replace(/\D/g, '').slice(-10);

      const isForMe = Boolean(
        (curId && oCustId && (curId === oCustId || curId.includes(oCustId) || oCustId.includes(curId))) ||
        (curEmail && oEmail && curEmail === oEmail) ||
        (curPhone && oPhone && curPhone.length >= 7 && (curPhone.endsWith(oPhone) || oPhone.endsWith(curPhone)))
      );

      if (isForMe) {
        setCustomerOrders(prev => {
          const ordId = String(data.id || data.order_number || data._id || '');
          const exists = prev.some(o => o && (String(o.id || o.order_number || o._id || '') === ordId));
          if (exists) return prev;
          return [data, ...prev];
        });
        loadCustomerOrders(true);
        if (typeof triggerNotification === 'function') {
          triggerNotification(`New ${data.type || 'order'} synced: #${data.order_number || data.id}`);
        }
      }
    };

    // 3. Saved Addresses Updated
    const handleAddressesUpdated = (data) => {
      if (data && Array.isArray(data.addresses)) {
        setAddresses(data.addresses);
        try {
          localStorage.setItem(`connect_customer_addresses_${customerId}`, JSON.stringify(data.addresses));
        } catch (e) {}
      }
    };

    // 4. Cart Updated on another platform
    const handleCartUpdated = (data) => {
      if (data && Array.isArray(data.cart)) {
        isRemoteCartUpdateRef.current = true;
        isCartInitializedRef.current = true;
        const sanitizedCart = data.cart.map(item => ({
          ...item,
          name: item.name || item.title || 'Cart Item',
          image: item.image || item.imageUrl || (Array.isArray(item.images) ? (item.images[0]?.url || item.images[0]) : '') || '',
          price: typeof item.price === 'string'
            ? (parseFloat(item.price.replace(/[^\d.]/g, '')) || 0)
            : Number(item.price || 0)
        }));
        setCart(sanitizedCart);
        try {
          localStorage.setItem('connect_cart', JSON.stringify(sanitizedCart));
        } catch (e) {}
      }
    };

    // 5. Wishlist / Favorites Updated on another platform
    const handleFavoritesUpdated = (data) => {
      if (data && Array.isArray(data.favorites)) {
        setFavorites(data.favorites);
        try {
          localStorage.setItem('connect_customer_favorites', JSON.stringify(data.favorites));
        } catch (e) {}
      }
    };

    // 6. Profile Updated on another platform
    const handleProfileUpdated = (data) => {
      if (data?.user) {
        if (data.user.name && typeof setProfileName === 'function') setProfileName(data.user.name);
        if (data.user.email && typeof setProfileEmail === 'function') setProfileEmail(data.user.email);
        if (data.user.phone && typeof setProfilePhone === 'function') setProfilePhone(data.user.phone);
        if (data.user.avatar && typeof setProfilePhoto === 'function') setProfilePhoto(data.user.avatar);
        if (Array.isArray(data.user.addresses)) setAddresses(data.user.addresses);
        if (typeof login === 'function' && currentUserRef.current) {
          login({ ...currentUserRef.current, ...data.user }, 'customer');
        }
      }
      if (Array.isArray(data?.cart)) {
        isRemoteCartUpdateRef.current = true;
        isCartInitializedRef.current = true;
        const sanitizedCart = data.cart.map(item => ({
          ...item,
          name: item.name || item.title || 'Cart Item',
          image: item.image || item.imageUrl || (Array.isArray(item.images) ? (item.images[0]?.url || item.images[0]) : '') || '',
          price: typeof item.price === 'string'
            ? (parseFloat(item.price.replace(/[^\d.]/g, '')) || 0)
            : Number(item.price || 0)
        }));
        setCart(sanitizedCart);
        try { localStorage.setItem('connect_cart', JSON.stringify(sanitizedCart)); } catch (e) {}
      }
      if (Array.isArray(data?.favorites)) {
        setFavorites(data.favorites);
        try { localStorage.setItem('connect_customer_favorites', JSON.stringify(data.favorites)); } catch (e) {}
      }
      if (typeof loadCustomerProfileFromDb === 'function') {
        loadCustomerProfileFromDb();
      }
    };

    socketService.on('order_status_updated', handleOrderStatus);
    socketService.on('customer_order_status', handleOrderStatus);
    socketService.on('new_order_placed', handleNewOrder);
    socketService.on('order_created', handleNewOrder);

    const handleNotificationsRead = () => {
      if (typeof loadCustomerNotifications === 'function') loadCustomerNotifications();
      else if (typeof fetchCustomerNotifications === 'function') fetchCustomerNotifications();
    };

    const handleCategoriesUpdated = () => {
      if (typeof fetchDbCategories === 'function') fetchDbCategories();
    };

    const handleMembershipUpdated = () => {
      if (typeof loadCustomerProfileFromDb === 'function') loadCustomerProfileFromDb();
    };

    socketService.on('addresses_updated', handleAddressesUpdated);
    socketService.on('cart_updated', handleCartUpdated);
    socketService.on('favorites_updated', handleFavoritesUpdated);
    socketService.on('customer_profile_updated', handleProfileUpdated);
    socketService.on('notifications_read', handleNotificationsRead);
    socketService.on('notification_created', handleNotificationsRead);
    socketService.on('customer_notification', handleNotificationsRead);
    socketService.on('categories:updated', handleCategoriesUpdated);
    socketService.on('membership_updated', handleMembershipUpdated);
    socketService.on('membership:updated', handleMembershipUpdated);

    return () => {
      socketService.off('order_status_updated', handleOrderStatus);
      socketService.off('customer_order_status', handleOrderStatus);
      socketService.off('new_order_placed', handleNewOrder);
      socketService.off('order_created', handleNewOrder);
      socketService.off('addresses_updated', handleAddressesUpdated);
      socketService.off('cart_updated', handleCartUpdated);
      socketService.off('favorites_updated', handleFavoritesUpdated);
      socketService.off('customer_profile_updated', handleProfileUpdated);
      socketService.off('notifications_read', handleNotificationsRead);
      socketService.off('notification_created', handleNotificationsRead);
      socketService.off('customer_notification', handleNotificationsRead);
      socketService.off('categories:updated', handleCategoriesUpdated);
      socketService.off('membership_updated', handleMembershipUpdated);
      socketService.off('membership:updated', handleMembershipUpdated);
    };
  }, [currentUser?.id, currentUser?.customerId, activeCustomerId]);

  // Listen for order history loads
  useEffect(() => {
    const activeUserId = currentUser?.id || currentUser?.customerId || currentUser?.email || '';
    if (activeUserId) {
      loadCustomerOrders();
    }
  }, [currentUser?.id, currentUser?.customerId, currentUser?.email]);

  useEffect(() => {
    if (isProfileModalOpen) {
      loadCustomerOrders();
    }
  }, [isProfileModalOpen]);


  // Clean network recovery and automatic cross-platform synchronization (No Manual Refresh)
  useEffect(() => {
    let lastSyncTime = 0;
    const triggerRevalidation = () => {
      const now = Date.now();
      if (now - lastSyncTime < 1500) return; // Debounce 1.5s
      lastSyncTime = now;
      if (typeof navigator !== 'undefined' && navigator.onLine) {
        if (typeof loadCustomerProfileFromDb === 'function') loadCustomerProfileFromDb();
        if (typeof loadCustomerOrders === 'function') loadCustomerOrders(true);
        if (typeof loadCustomerNotifications === 'function') loadCustomerNotifications();
      }
    };

    const handleOnline = () => {
      setTimeout(triggerRevalidation, 300);
    };

    const handleVisibilityChange = () => {
      if (typeof document !== 'undefined' && !document.hidden) {
        triggerRevalidation();
      }
    };

    const handleWindowFocus = () => {
      triggerRevalidation();
    };

    window.addEventListener('online', handleOnline);
    window.addEventListener('focus', handleWindowFocus);
    if (typeof document !== 'undefined') {
      document.addEventListener('visibilitychange', handleVisibilityChange);
    }

    socketService.on('socket_reconnected', triggerRevalidation);
    socketService.on('app_visibility_active', triggerRevalidation);
    socketService.on('app_network_online', handleOnline);

    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('focus', handleWindowFocus);
      if (typeof document !== 'undefined') {
        document.removeEventListener('visibilitychange', handleVisibilityChange);
      }
      socketService.off('socket_reconnected', triggerRevalidation);
      socketService.off('app_visibility_active', triggerRevalidation);
      socketService.off('app_network_online', handleOnline);
    };
  }, [loadCustomerProfileFromDb, loadCustomerOrders, loadCustomerNotifications]);

  const handleDeleteNotification = async (notifId) => {
    if (!notifId) return;
    try {
      const deletedIds = getDeletedNotificationIds();
      deletedIds.add(notifId);
      const cleanId = String(notifId).replace('ord-notif-', '');
      deletedIds.add(cleanId);
      if (typeof localStorage !== 'undefined') {
        localStorage.setItem('connect_deleted_notifications', JSON.stringify([...deletedIds]));
      }
      setNotificationsList(prev => prev.filter(n => n.id !== notifId && n.id !== cleanId));
      setUnreadCount(prev => Math.max(0, prev - 1));

      // Call backend DELETE endpoint
      try {
        await apiFetch(`/auth/customer-notifications/${cleanId}`, {
          method: 'DELETE'
        });
      } catch (e) {
        // Fallback endpoint
        try {
          await apiFetch(`/auth/notifications/${cleanId}`, { method: 'DELETE' });
        } catch (err) {}
      }

      triggerNotification("Notification removed");
    } catch (err) {
      console.warn("Failed deleting notification:", err);
      triggerNotification("Failed to delete notification", "error");
    }
  };

  const handleClearAllNotifications = () => {
    if (notificationsList.length === 0) return;
    const confirmClear = window.confirm("Are you sure you want to clear all notifications?");
    if (!confirmClear) return;

    try {
      const deletedIds = getDeletedNotificationIds();
      notificationsList.forEach(n => {
        if (n.id) {
          deletedIds.add(n.id);
          deletedIds.add(String(n.id).replace('ord-notif-', ''));
        }
      });
      if (typeof localStorage !== 'undefined') {
        localStorage.setItem('connect_deleted_notifications', JSON.stringify([...deletedIds]));
        localStorage.setItem('connect_notifications_cleared_at', String(Date.now()));
      }
      setNotificationsList([]);
      setUnreadCount(0);
      triggerNotification("All notifications cleared", "success");

      // Persist mark all read to backend
      apiFetch('/auth/customer-notifications/read', { method: 'PUT' }).catch(() => {});
    } catch (e) {
      console.warn("Failed clearing all notifications:", e);
    }
  };

  const handleNotificationClick = (notif) => {
    if (!notif) return;
    if (!notif.read) {
      try {
        const existing = getReadNotificationIds();
        if (notif.id) existing.add(notif.id);
        if (typeof localStorage !== 'undefined') {
          localStorage.setItem('connect_read_notifications', JSON.stringify([...existing]));
        }
      } catch (e) {}
      setNotificationsList(prev => prev.map(n => n.id === notif.id ? { ...n, read: true } : n));
      setUnreadCount(prev => Math.max(0, prev - 1));

      // Persist read status to backend MongoDB
      apiFetch('/auth/customer-notifications/read', {
        method: 'PUT',
        body: JSON.stringify({ id: notif.id, notificationId: notif.id })
      }).catch(() => {});
    }

    const entityId = notif.entityId || notif.orderId || String(notif.id).replace('ord-notif-', '');
    const matchedOrder = customerOrders.find(o => 
      String(o.id) === entityId || 
      String(o._id) === entityId || 
      String(o.order_number) === entityId
    ) || notif.order;

    setIsNotificationsOpen(false);
    setIsProfileModalOpen(true);

    if (matchedOrder) {
      const targetTab = getCustomerRecordClassification(matchedOrder);
      setActiveProfileTab(targetTab);
      if (targetTab === 'orders') setSelectedOrdersTab('All Orders');
      else if (targetTab === 'bookings') setSelectedOrdersTab('All Bookings');
      else if (targetTab === 'myjobs') setSelectedOrdersTab('All Applications');
      setTrackingOrder(matchedOrder);
    } else {
      const notifType = String(notif.type || '').toLowerCase();
      if (notifType === 'job' || notifType === 'jobs') {
        setActiveProfileTab('myjobs');
        setSelectedOrdersTab('All Applications');
      } else if (['booking', 'stay', 'travel', 'appointment', 'services', 'service'].includes(notifType)) {
        setActiveProfileTab('bookings');
        setSelectedOrdersTab('All Bookings');
      } else {
        setActiveProfileTab('orders');
        setSelectedOrdersTab('All Orders');
      }
    }
  };

  const markAllNotificationsAsRead = () => {
    try {
      const allIds = notificationsList.map(n => n.id);
      const existing = getReadNotificationIds();
      allIds.forEach(id => existing.add(id));
      if (typeof localStorage !== 'undefined') {
        localStorage.setItem('connect_read_notifications', JSON.stringify([...existing]));
      }
      setUnreadCount(0);
      setNotificationsList(prev => prev.map(n => ({ ...n, read: true })));
      triggerNotification("All notifications marked as read");

      // Persist bulk read status to backend MongoDB
      apiFetch('/auth/customer-notifications/read', {
        method: 'PUT'
      }).catch(() => {});
    } catch (err) {
      console.warn("Failed marking notifications read:", err);
    }
  };

  // Lock/unlock body scroll whenever any modal, drawer, or pop-up is open (Issue 20)
  useEffect(() => {
    const anyModalOpen = Boolean(
      isProfileModalOpen || 
      isWishlistOpen || 
      isCartOpen || 
      isCompareModalOpen || 
      isNotificationsOpen || 
      isMobileMenuOpen || 
      isLocationDropdownOpen || 
      shareModalProduct || 
      activeScheduleModalItem || 
      activeBookNowModalItem || 
      supportOrderModal || 
      isAddressModalOpen || 
      isRazorpayModalOpen || 
      isPayAtHotelConfirmOpen || 
      payAtHotelSuccessData || 
      membershipCheckoutModal || 
      isPreviewResumeOpen || 
      isLoginModalOpen
    );
    if (anyModalOpen) {
      document.body.style.overflow = 'hidden';
      document.body.style.touchAction = 'none';
      document.documentElement.style.overflow = 'hidden';
      if (mainScrollRef.current) {
        mainScrollRef.current.style.overflow = 'hidden';
      }
    } else {
      document.body.style.overflow = '';
      document.body.style.touchAction = '';
      document.documentElement.style.overflow = '';
      if (mainScrollRef.current) {
        mainScrollRef.current.style.overflow = '';
      }
    }
    return () => {
      document.body.style.overflow = '';
      document.body.style.touchAction = '';
      document.documentElement.style.overflow = '';
      if (mainScrollRef.current) {
        mainScrollRef.current.style.overflow = '';
      }
    };
  }, [
    isProfileModalOpen, isWishlistOpen, isCartOpen, isCompareModalOpen, 
    isNotificationsOpen, isMobileMenuOpen, isLocationDropdownOpen, 
    shareModalProduct, activeScheduleModalItem, activeBookNowModalItem, 
    supportOrderModal, isAddressModalOpen, 
    isRazorpayModalOpen, isPayAtHotelConfirmOpen, payAtHotelSuccessData, membershipCheckoutModal, isPreviewResumeOpen, isLoginModalOpen
  ]);

  // Hover Mega Menu State & Handlers
  const [hoveredLink, setHoveredLink] = useState(null);
  const [activeMegaCategory, setActiveMegaCategory] = useState('ALL');
  const enterTimeoutRef = React.useRef(null);
  const leaveTimeoutRef = React.useRef(null);

  const handleMouseEnter = (linkName) => {
    if (leaveTimeoutRef.current) clearTimeout(leaveTimeoutRef.current);
    if (enterTimeoutRef.current) clearTimeout(enterTimeoutRef.current);
    
    enterTimeoutRef.current = setTimeout(() => {
      setHoveredLink(linkName);
      setActiveMegaCategory('ALL');
      setSidebarActiveCat('ALL'); setSelectedCategories([]);
    }, 120); // 120ms responsive hover
  };

  const handleMouseLeave = () => {
    if (enterTimeoutRef.current) clearTimeout(enterTimeoutRef.current);
    if (leaveTimeoutRef.current) clearTimeout(leaveTimeoutRef.current);
    
    leaveTimeoutRef.current = setTimeout(() => {
      setHoveredLink(null);
    }, 150);
  };

  useEffect(() => {
    setSidebarActiveCat('ALL');
  }, [hoveredLink]);

  // Job Application States
  const [applicantName, setApplicantName] = useState(currentUser?.name || profileName || '');
  const [applicantEmail, setApplicantEmail] = useState(currentUser?.email || profileEmail || '');
  const [applicantResume, setApplicantResume] = useState('');
  const [isJobSubmitting, setIsJobSubmitting] = useState(false);
  const [jobSubmitSuccess, setJobSubmitSuccess] = useState(false);

  // Additional job application & orders tab state variables
  const [applicantPhone, setApplicantPhone] = useState(currentUser?.phone || '');
  const [applicantLocation, setApplicantLocation] = useState('');
  const [applicantLinkedIn, setApplicantLinkedIn] = useState(currentUser?.linkedin || '');
  const [applicantPortfolio, setApplicantPortfolio] = useState(currentUser?.portfolio || '');
  const [applicantExperience, setApplicantExperience] = useState('Fresher');
  const [applicantCurrentCompany, setApplicantCurrentCompany] = useState('');
  const [applicantNoticePeriod, setApplicantNoticePeriod] = useState('Immediate');
  const [resumeFile, setResumeFile] = useState(null);
  const [applicantCoverLetter, setApplicantCoverLetter] = useState('');

  // Travel Boarding & Dropping Points State
  const [boardingPoint, setBoardingPoint] = useState('');
  const [droppingPoint, setDroppingPoint] = useState('');

  // Sync applicant name/email when profile/user updates
  useEffect(() => {
    if (currentUser?.name || profileName) setApplicantName(currentUser?.name || profileName);
    if (currentUser?.email || profileEmail) setApplicantEmail(currentUser?.email || profileEmail);
    if (currentUser?.phone) setApplicantPhone(currentUser.phone);
  }, [currentUser, profileName, profileEmail]);

  // Reset transient job-specific form state when switching between jobs, preserving drafts if present (Bug K)
  const prevAppliedJobIdRef = useRef(appliedJobId);
  useEffect(() => {
    if (appliedJobId && appliedJobId !== prevAppliedJobIdRef.current) {
      prevAppliedJobIdRef.current = appliedJobId;
      setJobSubmitSuccess(false);

      const draftKey = `connect_job_draft_${appliedJobId}`;
      let savedDraft = null;
      try {
        const raw = localStorage.getItem(draftKey);
        if (raw) savedDraft = JSON.parse(raw);
      } catch (e) {}

      if (savedDraft) {
        setApplicantName(savedDraft.name || currentUser?.name || profileName || '');
        setApplicantEmail(savedDraft.email || currentUser?.email || profileEmail || '');
        setApplicantPhone(savedDraft.phone || (currentUser?.phone ? String(currentUser.phone).replace(/\D/g, '').slice(-10) : (profilePhone ? String(profilePhone).replace(/\D/g, '').slice(-10) : '')));
        setApplicantLocation(savedDraft.location || '');
        setApplicantCurrentCompany(savedDraft.currentCompany || '');
        setApplicantExperience(savedDraft.experience || 'Fresher');
        setApplicantNoticePeriod(savedDraft.noticePeriod || 'Immediate');
        setApplicantLinkedIn(savedDraft.linkedIn || currentUser?.linkedin || '');
        setApplicantPortfolio(savedDraft.portfolio || currentUser?.portfolio || '');
        setApplicantCoverLetter(savedDraft.coverLetter || '');
        if (savedDraft.resumeFile) {
          setResumeFile(savedDraft.resumeFile);
        } else {
          setResumeFile(null);
        }
      } else {
        setApplicantLocation('');
        setApplicantCurrentCompany('');
        setApplicantExperience('Fresher');
        setApplicantNoticePeriod('Immediate');
        setApplicantLinkedIn(currentUser?.linkedin || '');
        setApplicantPortfolio(currentUser?.portfolio || '');
        setResumeFile(null);
        setApplicantCoverLetter('');
      }
    } else if (!appliedJobId) {
      prevAppliedJobIdRef.current = null;
    }
  }, [appliedJobId, currentUser, profileName, profileEmail, profilePhone]);

  const handleOpenJobApplication = (jobId) => {
    setAppliedJobId(jobId);
    setJobSubmitSuccess(false);

    const draftKey = `connect_job_draft_${jobId}`;
    let savedDraft = null;
    try {
      const raw = localStorage.getItem(draftKey);
      if (raw) savedDraft = JSON.parse(raw);
    } catch (e) {}

    if (savedDraft) {
      setApplicantName(savedDraft.name || currentUser?.name || profileName || '');
      setApplicantEmail(savedDraft.email || currentUser?.email || profileEmail || '');
      setApplicantPhone(savedDraft.phone || (currentUser?.phone ? String(currentUser.phone).replace(/\D/g, '').slice(-10) : (profilePhone ? String(profilePhone).replace(/\D/g, '').slice(-10) : '')));
      setApplicantLocation(savedDraft.location || '');
      setApplicantCurrentCompany(savedDraft.currentCompany || '');
      setApplicantExperience(savedDraft.experience || 'Fresher');
      setApplicantNoticePeriod(savedDraft.noticePeriod || 'Immediate');
      setApplicantLinkedIn(savedDraft.linkedIn || currentUser?.linkedin || '');
      setApplicantPortfolio(savedDraft.portfolio || currentUser?.portfolio || '');
      setApplicantCoverLetter(savedDraft.coverLetter || '');
      if (savedDraft.resumeFile) {
        setResumeFile(savedDraft.resumeFile);
      } else {
        setResumeFile(null);
      }
      triggerNotification("Restored saved job draft.", "info");
    } else {
      setApplicantName(currentUser?.name || profileName || '');
      setApplicantEmail(currentUser?.email || profileEmail || '');
      setApplicantPhone(currentUser?.phone ? String(currentUser.phone).replace(/\D/g, '').slice(-10) : (profilePhone ? String(profilePhone).replace(/\D/g, '').slice(-10) : ''));
      setApplicantLocation('');
      setApplicantCurrentCompany('');
      setApplicantExperience('Fresher');
      setApplicantNoticePeriod('Immediate');
      setApplicantLinkedIn(currentUser?.linkedin || '');
      setApplicantPortfolio(currentUser?.portfolio || '');
      setResumeFile(null);
      setApplicantCoverLetter('');
    }
  };

  // When activeTab changes to Jobs, always show Jobs listing page first
  useEffect(() => {
    if (activeTab === 'Jobs') {
      setAppliedJobId(null);
      setJobSubmitSuccess(false);
      setResumeFile(null);
    }
  }, [activeTab]);

  const staticJobsList = [];

  const jobsList = [
    ...staticJobsList,
    ...products.filter(p => {
      if (!p) return false;
      const pFood = String(p.foodType || '').trim().toLowerCase();
      const pSub = String(p.subcategory || '').trim().toLowerCase();
      const pChild = String(p.subSubcategory || '').trim().toLowerCase();
      const pName = String(p.name || p.title || '').trim().toLowerCase();
      const pCat = String(p.category || '').trim().toLowerCase();
      const pMain = String(p.mainCategory || '').trim().toLowerCase();
      const pSubNav = String(p.subNavbarCategory || '').trim().toLowerCase();

      // Strict Exclusion: Food products must NEVER enter Jobs
      if (pFood && ['veg', 'non-veg', 'nonveg', 'idly', 'dosa', 'meals', 'standard'].includes(pFood)) {
        return false;
      }
      if (['dosa', 'idly', 'idli', 'south indian meals', 'biryani', 'parotta', 'chapati', 'poori', 'curry', 'meals'].some(k => pName === k || pName.includes(k) || pSub === k || pSub.includes(k) || pChild === k || pChild.includes(k))) {
        return false;
      }

      // Valid job category taxonomy from dbCategories or explicit job identifiers
      const isJobsTaxonomy = (
        pCat === 'it' || pCat === 'non-it' || pSub === 'it' || pSub === 'non-it' ||
        ['data analyst', 'full stack developer', 'data associate', 'system administrator'].some(j => pSub === j || pChild === j || pName.toLowerCase() === j)
      );

      const isJobListing = (isJobCardItem(p) || pSubNav === 'jobs' || pMain === 'jobs' || pCat === 'jobs') &&
        !['food', 'services', 'stay', 'travel', 'daily needs'].includes(normalizeMainCatName(p.subcategory)) &&
        !['food', 'services', 'stay', 'travel', 'daily needs'].includes(normalizeMainCatName(p.category));

      return isJobsTaxonomy || (isJobListing && (p.jobTitle || p.jobLocation || p.salary || p.experienceRequired || p.qualification || isJobsTaxonomy));
    }).map(p => {
      const vendorJobType = p.jobType || p.type || p.job_type || p.employmentType || p.workType;
      const vendorExp = p.experience || p.exp || p.jobExperience || p.experience_required || p.experienceRequired || p.minExperience;
      const vendorDept = p.department || p.category || p.jobCategory || p.specialization || p.subCategory;
      const vendorSalary = p.salary ? String(p.salary).trim() : (p.price ? `₹${(p.price || 0).toLocaleString()} L.P.A` : null);

      return {
        id: p.id || p._id,
        vendorId: p.vendorId,
        vendorName: p.vendorName || p.brand || p.companyName || p.vendor_name || 'Partner Organization',
        title: sanitizeJobTitle(p.jobTitle || p.title || p.name || p.role || p.designation),
        department: vendorDept || 'General',
        location: sanitizeJobLocation(p.jobLocation || p.location || p.city || p.vendorCity || p.locationType),
        salary: vendorSalary || 'Competitive Salary',
        type: vendorJobType || inferJobType(p),
        experience: vendorExp || inferExperience(p.description, p.name, vendorExp),
        skills: p.skills || p.skillsRequired || p.requiredSkills || p.qualification || p.tags,
        desc: p.description || p.jobDescription || p.desc || p.details || `${p.name || 'Job'} position.`,
        price: p.price,
        rating: p.rating,
        createdAt: p.createdAt || p.created_at || p.postedOn || p.postedDate || p.date,
        applicationTips: p.applicationTips || p.tips || p.instructions || p.howToApply
      };
    })
  ];

  const handleJobSubmit = async (e) => {
    if (e && e.preventDefault) e.preventDefault();
    if (!applicantName || !applicantName.trim()) {
      triggerNotification('Please enter your full name.', 'error');
      return;
    }
    const cleanName = applicantName.trim();
    if (/\d/.test(cleanName) || !/^[A-Za-z\s.'-]+$/.test(cleanName) || cleanName.length < 2) {
      triggerNotification('Please enter a valid candidate name (letters and spaces only, no numbers).', 'error');
      return;
    }
    if (!applicantEmail || !applicantEmail.trim()) {
      triggerNotification('Please enter your email address.', 'error');
      return;
    }
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!emailRegex.test(applicantEmail.trim())) {
      triggerNotification('Please enter a valid email address (e.g. name@example.com).', 'error');
      return;
    }
    if (!resumeFile) {
      triggerNotification('Please upload your resume before submitting your job application.', 'error');
      return;
    }
    setIsJobSubmitting(true);
    try {
      const selectedJob = jobsList.find(j => j.id === appliedJobId || String(j.id) === String(appliedJobId) || j._id === appliedJobId || String(j._id) === String(appliedJobId)) ||
        products.find(p => p.id === appliedJobId || String(p.id) === String(appliedJobId) || p._id === appliedJobId || String(p._id) === String(appliedJobId)) ||
        (selectedProduct && (selectedProduct.id === appliedJobId || String(selectedProduct.id) === String(appliedJobId)) ? selectedProduct : null) || {
          title: 'Full Stack Developer',
          id: appliedJobId || 'CAT-FSD-2026-1024',
          vendorId: ''
        };

      const jobTitle = selectedJob?.title || selectedJob?.name || selectedJob?.jobTitle || 'Job Application';
      const jobId = selectedJob?.id || selectedJob?._id || appliedJobId || 'CAT-FSD-2026-1024';
      const vendorId = selectedJob?.vendorId || selectedJob?.vendor_id || '';

      const custIdTarget = currentUser?.id || currentUser?.customerId || activeCustomerId || '';
      const custEmailTarget = applicantEmail || profileEmail || currentUser?.email || '';
      const custPhoneTarget = applicantPhone || profilePhone || currentUser?.phone || '';

      const generatedAppId = 'APP-' + new Date().getFullYear() + '-' + String(Math.floor(100000 + Math.random() * 900000));

      const res = await apiFetch('/orders', {
        method: 'POST',
        body: JSON.stringify({
          id: generatedAppId,
          order_number: generatedAppId,
          applicationId: generatedAppId,
          jobId: jobId,
          jobTitle: jobTitle,
          status: 'APPLICATION RECEIVED',
          vendor_id: vendorId,
          vendorId: vendorId,
          customer_id: custIdTarget,
          customerId: custIdTarget,
          user_id: custIdTarget,
          memberId: custIdTarget,
          customer_name: applicantName || currentUser?.name || 'Applicant',
          candidateName: applicantName || currentUser?.name || 'Applicant',
          customer_email: custEmailTarget,
          candidateEmail: custEmailTarget,
          customer_phone: custPhoneTarget,
          candidatePhone: custPhoneTarget,
          customer_address: applicantLocation || selectedLocation.area || 'Koramangala, Bangalore',
          jobLocation: applicantLocation || selectedLocation.area || 'Koramangala, Bangalore',
          customer_latitude: 12.9498,
          customer_longitude: 77.6289,
          product_details: jobTitle,
          amount: 0,
          items: [{
            productId: jobId,
            name: jobTitle,
            price: 0,
            quantity: 1
          }],
          candidateResume: resumeFile?.dataUrl || applicantResume || (resumeFile ? resumeFile.name : 'Dhanush_Resume.pdf'),
          experience: applicantExperience || 'Fresher',
          candidateEducation: 'Graduate',
          applicationDate: new Date().toISOString(),
          type: 'Job'
        })
      });

      if (res && (res.status === 'success' || res.id || res.order_number || res.data)) {
        try {
          localStorage.removeItem(`connect_job_draft_${jobId}`);
        } catch (e) {}

        const createdJobOrder = res.data && res.data.id ? res.data : {
          id: res.id || res.order_number || generatedAppId,
          order_number: res.order_number || res.id || generatedAppId,
          applicationId: res.applicationId || res.id || generatedAppId,
          jobId: jobId,
          jobTitle: jobTitle,
          status: 'APPLICATION RECEIVED',
          vendor_id: vendorId,
          vendorId: vendorId,
          customer_id: custIdTarget,
          customerId: custIdTarget,
          user_id: custIdTarget,
          memberId: custIdTarget,
          customer_name: applicantName || currentUser?.name || 'Applicant',
          candidateName: applicantName || currentUser?.name || 'Applicant',
          customer_email: custEmailTarget,
          candidateEmail: custEmailTarget,
          customer_phone: custPhoneTarget,
          candidatePhone: custPhoneTarget,
          customer_address: applicantLocation || selectedLocation.area || 'Koramangala, Bangalore',
          jobLocation: applicantLocation || selectedLocation.area || 'Koramangala, Bangalore',
          product_details: jobTitle,
          amount: 0,
          candidateResume: resumeFile?.dataUrl || applicantResume || (resumeFile ? resumeFile.name : 'Resume.pdf'),
          experience: applicantExperience || 'Fresher',
          candidateEducation: 'Graduate',
          applicationDate: new Date().toISOString(),
          createdAt: new Date().toISOString(),
          type: 'Job'
        };

        setCustomerOrders(prev => {
          const exists = prev.some(o => (o.id === createdJobOrder.id || (o.jobId === jobId && (o.customerId === custIdTarget || o.customer_email === custEmailTarget))));
          return exists ? prev : [createdJobOrder, ...prev];
        });

        try {
          const raw = localStorage.getItem('connect_user_orders') || '[]';
          const list = JSON.parse(raw);
          if (!list.some(o => (o.id === createdJobOrder.id || (o.jobId === jobId && (o.customerId === custIdTarget || o.customer_email === custEmailTarget))))) {
            list.unshift(createdJobOrder);
            localStorage.setItem('connect_user_orders', JSON.stringify(list));
          }
        } catch (e) {}

        setJobSubmitSuccess(true);
        triggerNotification(`Application for ${jobTitle} submitted successfully!`);
        loadCustomerOrders(true);
      } else if (res && (res.code === 'JOB_ALREADY_APPLIED' || res.message?.includes('already applied'))) {
        if (res.data) {
          const existingJobOrder = res.data;
          setCustomerOrders(prev => {
            const exists = prev.some(o => (o.id === existingJobOrder.id || o.jobId === jobId));
            return exists ? prev : [existingJobOrder, ...prev];
          });
          try {
            const raw = localStorage.getItem('connect_user_orders') || '[]';
            const list = JSON.parse(raw);
            if (!list.some(o => (o.id === existingJobOrder.id || o.jobId === jobId))) {
              list.unshift(existingJobOrder);
              localStorage.setItem('connect_user_orders', JSON.stringify(list));
            }
          } catch (e) {}
        }
        triggerNotification(res.message || 'You have already applied for this position.');
      } else {
        console.error('Failed to submit job application:', res);
        triggerNotification(res?.message || 'Failed to submit job application. Please try again.');
      }
    } catch (err) {
      console.error('Error placing job application:', err);
      triggerNotification('An error occurred while submitting your application.');
    } finally {
      setIsJobSubmitting(false);
    }
  };

  const handleBackToOpenings = () => {
    setAppliedJobId(null);
    setJobSubmitSuccess(false);
    setApplicantResume('');
  };

  // Membership Tier helper mapping
  const getMembershipTier = () => {
    const tierRaw = currentMembershipTier || 'Gold Elite';
    if (tierRaw.toLowerCase().includes('silver')) {
      return {
        name: 'Silver Member',
        colorClass: 'text-slate-400 dark:text-slate-300',
        bgClass: 'bg-slate-100 dark:bg-slate-800',
        badgeBg: 'bg-slate-400',
        badgeText: 'text-white',
        borderClass: 'border-slate-300 dark:border-slate-700',
        icon: Star,
        iconColor: 'text-slate-400 fill-slate-400'
      };
    }
    if (tierRaw.toLowerCase().includes('diamond')) {
      return {
        name: 'Diamond Member',
        colorClass: 'text-cyan-500 dark:text-cyan-400',
        bgClass: 'bg-cyan-50 dark:bg-cyan-950/40',
        badgeBg: 'bg-cyan-400',
        badgeText: 'text-cyan-950',
        borderClass: 'border-cyan-300 dark:border-cyan-800/40',
        icon: Gem,
        iconColor: 'text-cyan-400 fill-cyan-400'
      };
    }
    // Default Gold
    return {
      name: 'Gold Member',
      colorClass: 'text-amber-500 dark:text-amber-400',
      bgClass: 'bg-amber-50 dark:bg-amber-950/40',
      badgeBg: 'bg-amber-400',
      badgeText: 'text-[#0b1e36]',
      borderClass: 'border-amber-300 dark:border-amber-900/40',
      icon: Sparkles,
      iconColor: 'text-amber-400 fill-amber-400'
    };
  };

  const tier = getMembershipTier();

  const getCardStyle = () => {
    const nameLower = tier.name.toLowerCase();
    if (nameLower.includes('silver')) {
      return {
        cardBg: 'bg-gradient-to-tr from-slate-400 via-slate-100 to-slate-400',
        cardText: 'text-slate-800',
        cardBorder: 'border-slate-300',
        badgeBg: 'bg-slate-500/20 text-slate-700 border border-slate-500/30',
        brandText: 'text-slate-800',
        subText: 'text-slate-500',
        accentText: 'text-slate-800'
      };
    }
    if (nameLower.includes('diamond')) {
      return {
        cardBg: 'bg-gradient-to-tr from-cyan-400 via-cyan-100 to-cyan-400',
        cardText: 'text-cyan-950',
        cardBorder: 'border-cyan-300',
        badgeBg: 'bg-cyan-500/20 text-cyan-800 border border-cyan-500/30',
        brandText: 'text-cyan-900',
        subText: 'text-cyan-600',
        accentText: 'text-cyan-950'
      };
    }
    // Gold
    return {
      cardBg: 'bg-gradient-to-tr from-[#eed48f] via-[#fff3d4] to-[#eed48f]',
      cardText: 'text-[#5c3e07]',
      cardBorder: 'border-amber-300',
      badgeBg: 'bg-amber-400/20 border border-amber-400/30 text-[#704f05]',
      brandText: 'text-[#704f05]',
      subText: 'text-[#916b14]',
      accentText: 'text-[#704f05]'
    };
  };
  const cardStyle = getCardStyle();

  const jobMegaMenuData = {};
  const productMegaMenuData = {};
  const dailyNeedsMegaMenuData = {};
  const foodMegaMenuData = {};
  const stayMegaMenuData = {};
  const travelMegaMenuData = {};
  const serviceMegaMenuData = {};



  const mergeDbCategories = (mainCategoryName = '') => {
    let merged = {};
    const targetNorm = normalizeMainCatName(mainCategoryName);

    const catTree = buildActiveCategoryTree(dbCategories);
    const targetKey = Object.keys(catTree).find(k => normalizeMainCatName(k) === targetNorm) || mainCategoryName;
    const mainObj = catTree[targetKey];

    if (mainObj && mainObj.subcategories) {
      Object.keys(mainObj.subcategories).forEach(subName => {
        const subObj = mainObj.subcategories[subName];
        if (subObj && subObj.isActive !== false && !isMainCategoryName(subName)) {
          const sNameTrim = subName.trim();
          const cleanChildItems = Array.isArray(subObj.childCategories)
            ? subObj.childCategories
                .filter(Boolean)
                .map(c => typeof c === 'string' ? c.trim() : (c.name || '').trim())
                .filter(c => Boolean(c) && !isMainCategoryName(c) && c.toLowerCase() !== sNameTrim.toLowerCase())
            : [];
          merged[sNameTrim] = {
            title: sNameTrim,
            items: cleanChildItems
          };
        }
      });
    }

    const knownChildCategories = new Set(
      Object.values(merged).flatMap(s => s.items || []).map(i => String(i).toLowerCase())
    );

    // Supplement with categories extracted from live vendor products for this main category
    if (Array.isArray(products) && products.length > 0) {
      products.forEach(p => {
        if (!p || p.isActive === false || p.isAvailable === false) return;
        const pMain = normalizeMainCatName(p.subNavbarCategory || p.mainCategory || p.tag || '');
        if (pMain === targetNorm) {
          const rawSub = (p.subcategory || '').trim();
          const rawCat = (p.category && !isMainCategoryName(p.category) ? p.category : '').trim();
          const childName = (p.subSubcategory || '').trim();

          const existingSubKey = Object.keys(merged).find(k => 
            (rawSub && k.toLowerCase() === rawSub.toLowerCase()) || 
            (rawCat && k.toLowerCase() === rawCat.toLowerCase())
          );

          if (existingSubKey) {
            const itemToAdd = childName || (rawSub && rawCat && rawCat.toLowerCase() !== rawSub.toLowerCase() ? rawCat : '');
            if (itemToAdd && !isMainCategoryName(itemToAdd) && itemToAdd.toLowerCase() !== existingSubKey.toLowerCase() && !merged[existingSubKey].items.some(i => i.toLowerCase() === itemToAdd.toLowerCase())) {
              merged[existingSubKey].items.push(itemToAdd);
            }
          }
        }
      });
    }

    return merged;
  };

  const allMegaMenus = useMemo(() => {
    const menus = {
      'Services': mergeDbCategories('Services'),
      'Products': mergeDbCategories('Products'),
      'Daily Needs': mergeDbCategories('Daily Needs'),
      'Food': mergeDbCategories('Food'),
      'Stay': mergeDbCategories('Stay'),
      'Travel': mergeDbCategories('Travel'),
      'Jobs': mergeDbCategories('Jobs')
    };

    // Construct composite category mega menu for 'Home' tab
    const homeMenu = {};
    Object.values(menus).forEach(catDict => {
      if (catDict && typeof catDict === 'object') {
        Object.entries(catDict).forEach(([subName, subObj]) => {
          if (!subName || subName === 'ALL_SUBCATEGORIES_DELETED_MARKER') return;
          if (!homeMenu[subName]) {
            homeMenu[subName] = {
              title: subObj.title || subName,
              items: [...(subObj.items || [])]
            };
          } else {
            const mergedItems = new Set([...(homeMenu[subName].items || []), ...(subObj.items || [])]);
            homeMenu[subName].items = Array.from(mergedItems);
          }
        });
      }
    });
    menus['Home'] = homeMenu;

    // Also add any custom main categories that are not default
    subNavbarCategories.forEach(cat => {
      if (cat !== 'Home' && !menus[cat]) {
        menus[cat] = mergeDbCategories(cat);
      }
    });

    return menus;
  }, [dbCategories, products, subNavbarCategories]);

  const getCategoriesForTab = (tabName) => {
    const menuData = allMegaMenus[tabName] || {};
    const megaSubCats = Object.keys(menuData);

    const prodCats = products
      .filter(p => p.subNavbarCategory && normalizeMainCatName(p.subNavbarCategory) === normalizeMainCatName(tabName))
      .map(p => p.category)
      .filter(Boolean);

    const deletedCats = new Set();
    dbCategories.forEach(c => {
      if (!c) return;
      if (c.isDeleted || c.isActive === false || c.description === 'DELETED_HIERARCHY_MARKER') {
        if (c.subcategory) deletedCats.add(c.subcategory.toLowerCase());
        if (c.subSubcategory) deletedCats.add(c.subSubcategory.toLowerCase());
      }
    });

    const combined = [...new Set([...megaSubCats, ...prodCats])].filter(cat => !deletedCats.has(cat.toLowerCase()));
    return combined.sort();
  };


  // Filters State
  const [selectedCategories, setSelectedCategories] = useState([]);
  const [selectedBrands, setSelectedBrands] = useState([]);
  const [selectedColors, setSelectedColors] = useState([]);
  const [selectedPrices, setSelectedPrices] = useState([]);
  const [selectedRating, setSelectedRating] = useState(null);
  const [isMobileFiltersOpen, setIsMobileFiltersOpen] = useState(false);

